function traverse(
  node: TreeSitterNode,
  visitor: (node: TreeSitterNode) => void,
): void {
  visitor(node);
  for (let i = 0; i < node.childCount; i++) {
    const child = node.child(i);
    if (child) traverse(child, visitor);
  }
}

function getStringValue(node: TreeSitterNode): string {
  for (let i = 0; i < node.childCount; i++) {
    const child = node.child(i);
    if (child && child.type === "string_fragment") {
      return child.text;
    }
  }
  return node.text.replace(/^['"`]|['"`]$/g, "");
}

function findChild(node: TreeSitterNode, type: string): TreeSitterNode | null {
  for (let i = 0; i < node.childCount; i++) {
    const child = node.child(i);
    if (child && child.type === type) return child;
  }
  return null;
}

function findChildren(node: TreeSitterNode, type: string): TreeSitterNode[] {
  const result: TreeSitterNode[] = [];
  for (let i = 0; i < node.childCount; i++) {
    const child = node.child(i);
    if (child && child.type === type) result.push(child);
  }
  return result;
}

function hasChildOfType(node: TreeSitterNode, type: string): boolean {
  for (let i = 0; i < node.childCount; i++) {
    const child = node.child(i);
    if (child && child.type === type) return true;
  }
  return false;
}

function unwrapDeclaratorName(node: TreeSitterNode): string | null {
  if (node.type === "identifier" || node.type === "field_identifier") {
    return node.text;
  }
  // Dig into the nested declarator field
  const inner = node.childForFieldName("declarator");
  if (inner) {
    return unwrapDeclaratorName(inner);
  }
  // Fallback: look for direct identifier/field_identifier child
  const id = findChild(node, "identifier") ?? findChild(node, "field_identifier");
  return id ? id.text : null;
}

function extractFuncDeclName(
  funcDecl: TreeSitterNode,
): { name: string; qualifier: string | null } | null {
  const declNode = funcDecl.childForFieldName("declarator");
  if (!declNode) return null;

  if (declNode.type === "identifier" || declNode.type === "field_identifier") {
    return { name: declNode.text, qualifier: null };
  }

  if (declNode.type === "qualified_identifier") {
    const nameNode = declNode.childForFieldName("name");
    // The qualifier is the namespace_identifier before ::
    const nsNode = findChild(declNode, "namespace_identifier");
    return {
      name: nameNode ? nameNode.text : declNode.text,
      qualifier: nsNode ? nsNode.text : null,
    };
  }

  return { name: declNode.text, qualifier: null };
}

function extractParams(paramsNode: TreeSitterNode | null): string[] {
  if (!paramsNode) return [];
  const params: string[] = [];

  const decls = findChildren(paramsNode, "parameter_declaration");
  for (const decl of decls) {
    const declNode = decl.childForFieldName("declarator");
    if (declNode) {
      const name = unwrapDeclaratorName(declNode);
      if (name) {
        params.push(name);
      }
    }
  }

  return params;
}

function extractReturnType(node: TreeSitterNode): string | undefined {
  const typeNode = node.childForFieldName("type");
  if (typeNode) {
    return typeNode.text;
  }
  return undefined;
}

function isStatic(node: TreeSitterNode): boolean {
  const storage = findChild(node, "storage_class_specifier");
  return storage !== null && storage.text === "static";
}

class CppExtractor implements LanguageExtractor {
  readonly languageIds = ["cpp", "c"];

  extractStructure(rootNode: TreeSitterNode): StructuralAnalysis {
    const functions: StructuralAnalysis["functions"] = [];
    const classes: StructuralAnalysis["classes"] = [];
    const imports: StructuralAnalysis["imports"] = [];
    const exports: StructuralAnalysis["exports"] = [];

    // Track methods associated with classes via out-of-class definitions
    const methodsByClass = new Map<string, string[]>();

    this.walkTopLevel(rootNode, functions, classes, imports, exports, methodsByClass);

    // Attach out-of-class methods to their corresponding classes
    for (const cls of classes) {
      const methods = methodsByClass.get(cls.name);
      if (methods) {
        for (const m of methods) {
          if (!cls.methods.includes(m)) {
            cls.methods.push(m);
          }
        }
      }
    }

    return { functions, classes, imports, exports };
  }

  extractCallGraph(rootNode: TreeSitterNode): CallGraphEntry[] {
    const entries: CallGraphEntry[] = [];
    const functionStack: string[] = [];

    const walkForCalls = (node: TreeSitterNode) => {
      let pushedName = false;

      // Track entering function_definition
      if (node.type === "function_definition") {
        const name = this.extractFunctionName(node);
        if (name) {
          functionStack.push(name);
          pushedName = true;
        }
      }

      // Extract call_expression nodes
      if (node.type === "call_expression") {
        if (functionStack.length > 0) {
          const callee = this.extractCalleeName(node);
          if (callee) {
            entries.push({
              caller: functionStack[functionStack.length - 1],
              callee,
              lineNumber: node.startPosition.row + 1,
            });
          }
        }
      }

      for (let i = 0; i < node.childCount; i++) {
        const child = node.child(i);
        if (child) walkForCalls(child);
      }

      if (pushedName) {
        functionStack.pop();
      }
    };

    walkForCalls(rootNode);

    return entries;
  }

  // ---- Private helpers ----

  /**
   * Walk top-level declarations. Recurses into namespace_definition bodies
   * to find nested declarations.
   */
  private walkTopLevel(
    parentNode: TreeSitterNode,
    functions: StructuralAnalysis["functions"],
    classes: StructuralAnalysis["classes"],
    imports: StructuralAnalysis["imports"],
    exports: StructuralAnalysis["exports"],
    methodsByClass: Map<string, string[]>,
  ): void {
    for (let i = 0; i < parentNode.childCount; i++) {
      const node = parentNode.child(i);
      if (!node) continue;

      switch (node.type) {
        case "preproc_include":
          this.extractInclude(node, imports);
          break;

        case "class_specifier":
          this.extractClassOrStruct(node, "class", classes, functions, exports);
          break;

        case "struct_specifier":
          this.extractClassOrStruct(node, "struct", classes, functions, exports);
          break;

        case "function_definition":
          this.extractFunctionDef(node, functions, exports, methodsByClass);
          break;

        case "namespace_definition": {
          // Recurse into namespace body (declaration_list)
          const body = findChild(node, "declaration_list");
          if (body) {
            this.walkTopLevel(body, functions, classes, imports, exports, methodsByClass);
          }
          break;
        }

        case "declaration": {
          // A top-level ";" terminated statement — could be a class/struct with a trailing ;
          // e.g., `class Foo { ... };` parses the class_specifier as a child of a
          // declaration in some contexts. Check for nested class/struct specifiers.
          const innerClass = findChild(node, "class_specifier");
          if (innerClass) {
            this.extractClassOrStruct(innerClass, "class", classes, functions, exports);
          }
          const innerStruct = findChild(node, "struct_specifier");
          if (innerStruct) {
            this.extractClassOrStruct(innerStruct, "struct", classes, functions, exports);
          }
          break;
        }
      }
    }
  }

  /**
   * Extract the simple function name from a function_definition.
   * For qualified names (e.g., Server::start), returns just the method name.
   */
  private extractFunctionName(node: TreeSitterNode): string | null {
    const declNode = node.childForFieldName("declarator");
    if (!declNode || declNode.type !== "function_declarator") return null;

    const info = extractFuncDeclName(declNode);
    return info ? info.name : null;
  }

  /**
   * Extract #include directives and map them to the imports array.
   *
   * `preproc_include` has a `path` field that is either:
   * - `system_lib_string` for angle-bracket includes: `<iostream>`
   * - `string_literal` for quoted includes: `"myfile.h"`
   */
  private extractInclude(
    node: TreeSitterNode,
    imports: StructuralAnalysis["imports"],
  ): void {
    const pathNode = node.childForFieldName("path");
    if (!pathNode) return;

    let source: string;
    if (pathNode.type === "system_lib_string") {
      // Strip angle brackets: <iostream> -> iostream
      source = pathNode.text.replace(/^<|>$/g, "");
    } else if (pathNode.type === "string_literal") {
      // Extract content from string: "myfile.h" -> myfile.h
      const content = findChild(pathNode, "string_content");
      source = content ? content.text : pathNode.text.replace(/^"|"$/g, "");
    } else {
      source = pathNode.text;
    }

    imports.push({
      source,
      specifiers: [source],
      lineNumber: node.startPosition.row + 1,
    });
  }

  /**
   * Extract class_specifier or struct_specifier into the classes array.
   *
   * Processes:
   * - Properties (field_declaration without function_declarator)
   * - Method declarations (field_declaration with function_declarator)
   * - Method definitions (function_definition inside the class body)
   * - Access specifiers (public/private/protected)
   *
   * Public members of classes and all members of structs (default public)
   * are treated as exports.
   */
  private extractClassOrStruct(
    node: TreeSitterNode,
    kind: "class" | "struct",
    classes: StructuralAnalysis["classes"],
    functions: StructuralAnalysis["functions"],
    exports: StructuralAnalysis["exports"],
  ): void {
    const nameNode = node.childForFieldName("name");
    if (!nameNode) return;

    const className = nameNode.text;
    const methods: string[] = [];
    const properties: string[] = [];

    const body = node.childForFieldName("body");
    if (body && body.type === "field_declaration_list") {
      // Default access: public for struct, private for class
      let currentAccess = kind === "struct" ? "public" : "private";

      for (let j = 0; j < body.childCount; j++) {
        const member = body.child(j);
        if (!member) continue;

        if (member.type === "access_specifier") {
          // Update current access level
          const specChild = member.child(0);
          if (specChild) {
            currentAccess = specChild.text;
          }
          continue;
        }

        if (member.type === "field_declaration") {
          const declNode = member.childForFieldName("declarator");
          if (declNode && declNode.type === "function_declarator") {
            // Method declaration (no body)
            const info = extractFuncDeclName(declNode);
            if (info) {
              methods.push(info.name);
              if (currentAccess === "public") {
                exports.push({
                  name: info.name,
                  lineNumber: member.startPosition.row + 1,
                });
              }
            }
          } else if (declNode) {
            // Property (field_identifier or other declarator)
            const name = unwrapDeclaratorName(declNode);
            if (name) {
              properties.push(name);
            }
          }
        }

        if (member.type === "function_definition") {
          // Inline method definition
          const funcDecl = member.childForFieldName("declarator");
          if (funcDecl && funcDecl.type === "function_declarator") {
            const info = extractFuncDeclName(funcDecl);
            if (info) {
              methods.push(info.name);

              // Also add to functions list with params/return type
              const paramsNode = funcDecl.childForFieldName("parameters");
              functions.push({
                name: info.name,
                owner: className,
                lineRange: [
                  member.startPosition.row + 1,
                  member.endPosition.row + 1,
                ],
                params: extractParams(paramsNode),
                returnType: extractReturnType(member),
              });

              if (currentAccess === "public") {
                exports.push({
                  name: info.name,
                  lineNumber: member.startPosition.row + 1,
                });
              }
            }
          }
        }
      }
    }

    classes.push({
      name: className,
      lineRange: [
        node.startPosition.row + 1,
        node.endPosition.row + 1,
      ],
      methods,
      properties,
    });

    // The class/struct name itself is an export (non-anonymous types are always exported in C/C++ headers)
    exports.push({
      name: className,
      lineNumber: node.startPosition.row + 1,
    });
  }

  /**
   * Extract a free function or out-of-class method definition.
   *
   * For qualified names (e.g., `void Server::start()`), the method is:
   * - Added to the functions array
   * - Tracked in methodsByClass for later association with the class
   * - Exported if non-static
   *
   * Static functions are NOT exported.
   */
  private extractFunctionDef(
    node: TreeSitterNode,
    functions: StructuralAnalysis["functions"],
    exports: StructuralAnalysis["exports"],
    methodsByClass: Map<string, string[]>,
  ): void {
    const funcDecl = node.childForFieldName("declarator");
    if (!funcDecl || funcDecl.type !== "function_declarator") return;

    const info = extractFuncDeclName(funcDecl);
    if (!info) return;

    const paramsNode = funcDecl.childForFieldName("parameters");
    const params = extractParams(paramsNode);
    const returnType = extractReturnType(node);

    functions.push({
      name: info.name,
      owner: info.qualifier ?? "",
      lineRange: [
        node.startPosition.row + 1,
        node.endPosition.row + 1,
      ],
      params,
      returnType,
    });

    // Track out-of-class method definitions (e.g., void Server::start())
    if (info.qualifier) {
      if (!methodsByClass.has(info.qualifier)) {
        methodsByClass.set(info.qualifier, []);
      }
      methodsByClass.get(info.qualifier)!.push(info.name);
    }

    // Non-static top-level functions are exports
    if (!isStatic(node)) {
      exports.push({
        name: info.name,
        lineNumber: node.startPosition.row + 1,
      });
    }
  }

  /**
   * Extract the callee name from a call_expression.
   *
   * Handles:
   * - Plain function call: `printf(...)` -> "printf"
   * - Member call via field_expression: `p->method()` -> "p->method"
   * - Scoped call: `std::cout << ...` -> qualified name text
   */
  private extractCalleeName(callNode: TreeSitterNode): string | null {
    const funcNode = callNode.child(0);
    if (!funcNode) return null;

    if (funcNode.type === "identifier") {
      return funcNode.text;
    }

    if (funcNode.type === "field_expression") {
      const field = funcNode.childForFieldName("field");
      return field ? field.text : funcNode.text;
    }

    if (funcNode.type === "qualified_identifier") {
      return funcNode.text;
    }

    return funcNode.text;
  }
}

extractStructure(rootNode: TreeSitterNode): StructuralAnalysis {
    const functions: StructuralAnalysis["functions"] = [];
    const classes: StructuralAnalysis["classes"] = [];
    const imports: StructuralAnalysis["imports"] = [];
    const exports: StructuralAnalysis["exports"] = [];

    // Track methods associated with classes via out-of-class definitions
    const methodsByClass = new Map<string, string[]>();

    this.walkTopLevel(rootNode, functions, classes, imports, exports, methodsByClass);

    // Attach out-of-class methods to their corresponding classes
    for (const cls of classes) {
      const methods = methodsByClass.get(cls.name);
      if (methods) {
        for (const m of methods) {
          if (!cls.methods.includes(m)) {
            cls.methods.push(m);
          }
        }
      }
    }

    return { functions, classes, imports, exports };
  }

extractCallGraph(rootNode: TreeSitterNode): CallGraphEntry[] {
    const entries: CallGraphEntry[] = [];
    const functionStack: string[] = [];

    const walkForCalls = (node: TreeSitterNode) => {
      let pushedName = false;

      // Track entering function_definition
      if (node.type === "function_definition") {
        const name = this.extractFunctionName(node);
        if (name) {
          functionStack.push(name);
          pushedName = true;
        }
      }

      // Extract call_expression nodes
      if (node.type === "call_expression") {
        if (functionStack.length > 0) {
          const callee = this.extractCalleeName(node);
          if (callee) {
            entries.push({
              caller: functionStack[functionStack.length - 1],
              callee,
              lineNumber: node.startPosition.row + 1,
            });
          }
        }
      }

      for (let i = 0; i < node.childCount; i++) {
        const child = node.child(i);
        if (child) walkForCalls(child);
      }

      if (pushedName) {
        functionStack.pop();
      }
    };

    walkForCalls(rootNode);

    return entries;
  }

private walkTopLevel(
    parentNode: TreeSitterNode,
    functions: StructuralAnalysis["functions"],
    classes: StructuralAnalysis["classes"],
    imports: StructuralAnalysis["imports"],
    exports: StructuralAnalysis["exports"],
    methodsByClass: Map<string, string[]>,
  ): void {
    for (let i = 0; i < parentNode.childCount; i++) {
      const node = parentNode.child(i);
      if (!node) continue;

      switch (node.type) {
        case "preproc_include":
          this.extractInclude(node, imports);
          break;

        case "class_specifier":
          this.extractClassOrStruct(node, "class", classes, functions, exports);
          break;

        case "struct_specifier":
          this.extractClassOrStruct(node, "struct", classes, functions, exports);
          break;

        case "function_definition":
          this.extractFunctionDef(node, functions, exports, methodsByClass);
          break;

        case "namespace_definition": {
          // Recurse into namespace body (declaration_list)
          const body = findChild(node, "declaration_list");
          if (body) {
            this.walkTopLevel(body, functions, classes, imports, exports, methodsByClass);
          }
          break;
        }

        case "declaration": {
          // A top-level ";" terminated statement — could be a class/struct with a trailing ;
          // e.g., `class Foo { ... };` parses the class_specifier as a child of a
          // declaration in some contexts. Check for nested class/struct specifiers.
          const innerClass = findChild(node, "class_specifier");
          if (innerClass) {
            this.extractClassOrStruct(innerClass, "class", classes, functions, exports);
          }
          const innerStruct = findChild(node, "struct_specifier");
          if (innerStruct) {
            this.extractClassOrStruct(innerStruct, "struct", classes, functions, exports);
          }
          break;
        }
      }
    }
  }

private extractFunctionName(node: TreeSitterNode): string | null {
    const declNode = node.childForFieldName("declarator");
    if (!declNode || declNode.type !== "function_declarator") return null;

    const info = extractFuncDeclName(declNode);
    return info ? info.name : null;
  }

private extractInclude(
    node: TreeSitterNode,
    imports: StructuralAnalysis["imports"],
  ): void {
    const pathNode = node.childForFieldName("path");
    if (!pathNode) return;

    let source: string;
    if (pathNode.type === "system_lib_string") {
      // Strip angle brackets: <iostream> -> iostream
      source = pathNode.text.replace(/^<|>$/g, "");
    } else if (pathNode.type === "string_literal") {
      // Extract content from string: "myfile.h" -> myfile.h
      const content = findChild(pathNode, "string_content");
      source = content ? content.text : pathNode.text.replace(/^"|"$/g, "");
    } else {
      source = pathNode.text;
    }

    imports.push({
      source,
      specifiers: [source],
      lineNumber: node.startPosition.row + 1,
    });
  }

private extractClassOrStruct(
    node: TreeSitterNode,
    kind: "class" | "struct",
    classes: StructuralAnalysis["classes"],
    functions: StructuralAnalysis["functions"],
    exports: StructuralAnalysis["exports"],
  ): void {
    const nameNode = node.childForFieldName("name");
    if (!nameNode) return;

    const className = nameNode.text;
    const methods: string[] = [];
    const properties: string[] = [];

    const body = node.childForFieldName("body");
    if (body && body.type === "field_declaration_list") {
      // Default access: public for struct, private for class
      let currentAccess = kind === "struct" ? "public" : "private";

      for (let j = 0; j < body.childCount; j++) {
        const member = body.child(j);
        if (!member) continue;

        if (member.type === "access_specifier") {
          // Update current access level
          const specChild = member.child(0);
          if (specChild) {
            currentAccess = specChild.text;
          }
          continue;
        }

        if (member.type === "field_declaration") {
          const declNode = member.childForFieldName("declarator");
          if (declNode && declNode.type === "function_declarator") {
            // Method declaration (no body)
            const info = extractFuncDeclName(declNode);
            if (info) {
              methods.push(info.name);
              if (currentAccess === "public") {
                exports.push({
                  name: info.name,
                  lineNumber: member.startPosition.row + 1,
                });
              }
            }
          } else if (declNode) {
            // Property (field_identifier or other declarator)
            const name = unwrapDeclaratorName(declNode);
            if (name) {
              properties.push(name);
            }
          }
        }

        if (member.type === "function_definition") {
          // Inline method definition
          const funcDecl = member.childForFieldName("declarator");
          if (funcDecl && funcDecl.type === "function_declarator") {
            const info = extractFuncDeclName(funcDecl);
            if (info) {
              methods.push(info.name);

              // Also add to functions list with params/return type
              const paramsNode = funcDecl.childForFieldName("parameters");
              functions.push({
                name: info.name,
                owner: className,
                lineRange: [
                  member.startPosition.row + 1,
                  member.endPosition.row + 1,
                ],
                params: extractParams(paramsNode),
                returnType: extractReturnType(member),
              });

              if (currentAccess === "public") {
                exports.push({
                  name: info.name,
                  lineNumber: member.startPosition.row + 1,
                });
              }
            }
          }
        }
      }
    }

    classes.push({
      name: className,
      lineRange: [
        node.startPosition.row + 1,
        node.endPosition.row + 1,
      ],
      methods,
      properties,
    });

    // The class/struct name itself is an export (non-anonymous types are always exported in C/C++ headers)
    exports.push({
      name: className,
      lineNumber: node.startPosition.row + 1,
    });
  }

private extractFunctionDef(
    node: TreeSitterNode,
    functions: StructuralAnalysis["functions"],
    exports: StructuralAnalysis["exports"],
    methodsByClass: Map<string, string[]>,
  ): void {
    const funcDecl = node.childForFieldName("declarator");
    if (!funcDecl || funcDecl.type !== "function_declarator") return;

    const info = extractFuncDeclName(funcDecl);
    if (!info) return;

    const paramsNode = funcDecl.childForFieldName("parameters");
    const params = extractParams(paramsNode);
    const returnType = extractReturnType(node);

    functions.push({
      name: info.name,
      owner: info.qualifier ?? "",
      lineRange: [
        node.startPosition.row + 1,
        node.endPosition.row + 1,
      ],
      params,
      returnType,
    });

    // Track out-of-class method definitions (e.g., void Server::start())
    if (info.qualifier) {
      if (!methodsByClass.has(info.qualifier)) {
        methodsByClass.set(info.qualifier, []);
      }
      methodsByClass.get(info.qualifier)!.push(info.name);
    }

    // Non-static top-level functions are exports
    if (!isStatic(node)) {
      exports.push({
        name: info.name,
        lineNumber: node.startPosition.row + 1,
      });
    }
  }

private extractCalleeName(callNode: TreeSitterNode): string | null {
    const funcNode = callNode.child(0);
    if (!funcNode) return null;

    if (funcNode.type === "identifier") {
      return funcNode.text;
    }

    if (funcNode.type === "field_expression") {
      const field = funcNode.childForFieldName("field");
      return field ? field.text : funcNode.text;
    }

    if (funcNode.type === "qualified_identifier") {
      return funcNode.text;
    }

    return funcNode.text;
  }

function extractParams(paramsNode: TreeSitterNode | null): string[] {
  if (!paramsNode) return [];
  const params: string[] = [];

  const paramNodes = findChildren(paramsNode, "parameter");
  for (const param of paramNodes) {
    const nameNode = param.childForFieldName("name");
    if (nameNode) {
      params.push(nameNode.text);
    }
  }

  return params;
}

function extractReturnType(node: TreeSitterNode): string | undefined {
  const typeNode = node.childForFieldName("returns");
  if (!typeNode) return undefined;
  return typeNode.text;
}

function hasModifier(node: TreeSitterNode, modifier: string): boolean {
  const modifierNodes = findChildren(node, "modifier");
  for (const mod of modifierNodes) {
    for (let i = 0; i < mod.childCount; i++) {
      const child = mod.child(i);
      if (child && child.text === modifier) return true;
    }
  }
  return false;
}

function extractUsingSource(node: TreeSitterNode): string | null {
  // Check for alias form: `using Alias = Some.Namespace;`
  const hasEquals = findChild(node, "=") !== null;

  if (hasEquals) {
    // The target namespace is the qualified_name after the `=`
    const qualifiedName = findChild(node, "qualified_name");
    return qualifiedName ? qualifiedName.text : null;
  }

  // Simple or qualified using
  const qualifiedName = findChild(node, "qualified_name");
  if (qualifiedName) return qualifiedName.text;

  const identifier = findChild(node, "identifier");
  return identifier ? identifier.text : null;
}

function lastComponent(path: string): string {
  const parts = path.split(".");
  return parts[parts.length - 1];
}

function extractInvocationName(node: TreeSitterNode): string | null {
  const funcNode = node.childForFieldName("function");
  if (!funcNode) return null;
  return funcNode.text;
}

class CSharpExtractor implements LanguageExtractor {
  readonly languageIds = ["csharp"];

  extractStructure(rootNode: TreeSitterNode): StructuralAnalysis {
    const functions: StructuralAnalysis["functions"] = [];
    const classes: StructuralAnalysis["classes"] = [];
    const imports: StructuralAnalysis["imports"] = [];
    const exports: StructuralAnalysis["exports"] = [];

    this.walkTopLevel(rootNode, functions, classes, imports, exports);

    return { functions, classes, imports, exports };
  }

  extractCallGraph(rootNode: TreeSitterNode): CallGraphEntry[] {
    const entries: CallGraphEntry[] = [];
    const functionStack: string[] = [];

    const walkForCalls = (node: TreeSitterNode) => {
      let pushedName = false;

      // Track entering method/constructor declarations
      if (
        node.type === "method_declaration" ||
        node.type === "constructor_declaration"
      ) {
        const nameNode = node.childForFieldName("name");
        if (nameNode) {
          functionStack.push(nameNode.text);
          pushedName = true;
        }
      }

      // Extract method invocations: e.g. FetchFromDb(limit), Console.WriteLine(msg)
      if (node.type === "invocation_expression") {
        if (functionStack.length > 0) {
          const callee = extractInvocationName(node);
          if (callee) {
            entries.push({
              caller: functionStack[functionStack.length - 1],
              callee,
              lineNumber: node.startPosition.row + 1,
            });
          }
        }
      }

      // Extract object creation: e.g. new Foo()
      if (node.type === "object_creation_expression") {
        if (functionStack.length > 0) {
          // The type is the child after `new` — can be identifier or generic_name
          const typeNode = findChild(node, "identifier") ?? findChild(node, "generic_name");
          if (typeNode) {
            entries.push({
              caller: functionStack[functionStack.length - 1],
              callee: `new ${typeNode.text}`,
              lineNumber: node.startPosition.row + 1,
            });
          }
        }
      }

      for (let i = 0; i < node.childCount; i++) {
        const child = node.child(i);
        if (child) walkForCalls(child);
      }

      if (pushedName) {
        functionStack.pop();
      }
    };

    walkForCalls(rootNode);

    return entries;
  }

  // ---- Private helpers ----

  /**
   * Walk the top-level nodes of a compilation_unit, recursing into
   * namespace bodies to find declarations.
   */
  private walkTopLevel(
    node: TreeSitterNode,
    functions: StructuralAnalysis["functions"],
    classes: StructuralAnalysis["classes"],
    imports: StructuralAnalysis["imports"],
    exports: StructuralAnalysis["exports"],
  ): void {
    for (let i = 0; i < node.childCount; i++) {
      const child = node.child(i);
      if (!child) continue;

      switch (child.type) {
        case "using_directive":
          this.extractUsing(child, imports);
          break;

        case "namespace_declaration":
          // Recurse into namespace body (declaration_list)
          this.walkNamespaceBody(child, functions, classes, imports, exports);
          break;

        case "file_scoped_namespace_declaration":
          // File-scoped namespace: declarations are siblings at the root,
          // not children of this node. Nothing to recurse into.
          break;

        case "class_declaration":
        case "record_declaration":
        case "struct_declaration":
          this.extractClass(child, functions, classes, exports);
          break;

        case "interface_declaration":
          this.extractInterface(child, functions, classes, exports);
          break;
      }
    }
  }

  /**
   * Walk into a namespace_declaration's body (declaration_list) to find
   * classes, interfaces, and nested namespaces.
   */
  private walkNamespaceBody(
    nsNode: TreeSitterNode,
    functions: StructuralAnalysis["functions"],
    classes: StructuralAnalysis["classes"],
    imports: StructuralAnalysis["imports"],
    exports: StructuralAnalysis["exports"],
  ): void {
    const body = nsNode.childForFieldName("body");
    if (!body) return;

    for (let i = 0; i < body.childCount; i++) {
      const child = body.child(i);
      if (!child) continue;

      switch (child.type) {
        case "class_declaration":
        case "record_declaration":
        case "struct_declaration":
          this.extractClass(child, functions, classes, exports);
          break;

        case "interface_declaration":
          this.extractInterface(child, functions, classes, exports);
          break;

        case "namespace_declaration":
          // Nested namespaces
          this.walkNamespaceBody(child, functions, classes, imports, exports);
          break;
      }
    }
  }

  private extractUsing(
    node: TreeSitterNode,
    imports: StructuralAnalysis["imports"],
  ): void {
    const source = extractUsingSource(node);
    if (!source) return;

    imports.push({
      source,
      specifiers: [lastComponent(source)],
      lineNumber: node.startPosition.row + 1,
    });
  }

  private extractClass(
    node: TreeSitterNode,
    functions: StructuralAnalysis["functions"],
    classes: StructuralAnalysis["classes"],
    exports: StructuralAnalysis["exports"],
  ): void {
    const nameNode = node.childForFieldName("name");
    if (!nameNode) return;

    const methods: string[] = [];
    const properties: string[] = [];

    const body = node.childForFieldName("body");
    if (body) {
      this.extractClassBodyMembers(body, methods, properties, functions, exports);
    }

    classes.push({
      name: nameNode.text,
      lineRange: [
        node.startPosition.row + 1,
        node.endPosition.row + 1,
      ],
      methods,
      properties,
    });

    if (hasModifier(node, "public")) {
      exports.push({
        name: nameNode.text,
        lineNumber: node.startPosition.row + 1,
      });
    }
  }

  private extractInterface(
    node: TreeSitterNode,
    functions: StructuralAnalysis["functions"],
    classes: StructuralAnalysis["classes"],
    exports: StructuralAnalysis["exports"],
  ): void {
    const nameNode = node.childForFieldName("name");
    if (!nameNode) return;

    const methods: string[] = [];
    const properties: string[] = [];

    const body = node.childForFieldName("body");
    if (body) {
      // Interface body contains method_declaration nodes (signatures without bodies)
      const methodNodes = findChildren(body, "method_declaration");
      for (const methodNode of methodNodes) {
        const methNameNode = methodNode.childForFieldName("name");
        if (methNameNode) {
          methods.push(methNameNode.text);
        }
      }

      // Interface can contain property_declaration nodes
      const propNodes = findChildren(body, "property_declaration");
      for (const propNode of propNodes) {
        const propNameNode = propNode.childForFieldName("name");
        if (propNameNode) {
          properties.push(propNameNode.text);
        }
      }
    }

    classes.push({
      name: nameNode.text,
      lineRange: [
        node.startPosition.row + 1,
        node.endPosition.row + 1,
      ],
      methods,
      properties,
    });

    if (hasModifier(node, "public")) {
      exports.push({
        name: nameNode.text,
        lineNumber: node.startPosition.row + 1,
      });
    }
  }

  /**
   * Extract methods, constructors, properties, and fields from a
   * class declaration_list body.
   */
  private extractClassBodyMembers(
    body: TreeSitterNode,
    methods: string[],
    properties: string[],
    functions: StructuralAnalysis["functions"],
    exports: StructuralAnalysis["exports"],
  ): void {
    for (let i = 0; i < body.childCount; i++) {
      const child = body.child(i);
      if (!child) continue;

      switch (child.type) {
        case "method_declaration":
          this.extractMethod(child, methods, functions, exports);
          break;

        case "constructor_declaration":
          this.extractConstructor(child, methods, functions, exports);
          break;

        case "property_declaration":
          this.extractProperty(child, properties, exports);
          break;

        case "field_declaration":
          this.extractField(child, properties, exports);
          break;
      }
    }
  }

  private extractMethod(
    node: TreeSitterNode,
    methods: string[],
    functions: StructuralAnalysis["functions"],
    exports: StructuralAnalysis["exports"],
  ): void {
    const nameNode = node.childForFieldName("name");
    if (!nameNode) return;

    const paramsNode = node.childForFieldName("parameters");
    const params = extractParams(paramsNode ?? null);
    const returnType = extractReturnType(node);

    methods.push(nameNode.text);

    functions.push({
      name: nameNode.text,
      lineRange: [
        node.startPosition.row + 1,
        node.endPosition.row + 1,
      ],
      params,
      returnType,
    });

    if (hasModifier(node, "public")) {
      exports.push({
        name: nameNode.text,
        lineNumber: node.startPosition.row + 1,
      });
    }
  }

  private extractConstructor(
    node: TreeSitterNode,
    methods: string[],
    functions: StructuralAnalysis["functions"],
    exports: StructuralAnalysis["exports"],
  ): void {
    const nameNode = node.childForFieldName("name");
    if (!nameNode) return;

    const paramsNode = node.childForFieldName("parameters");
    const params = extractParams(paramsNode ?? null);

    methods.push(nameNode.text);

    functions.push({
      name: nameNode.text,
      lineRange: [
        node.startPosition.row + 1,
        node.endPosition.row + 1,
      ],
      params,
      // Constructors have no return type
    });

    if (hasModifier(node, "public")) {
      exports.push({
        name: nameNode.text,
        lineNumber: node.startPosition.row + 1,
      });
    }
  }

  private extractProperty(
    node: TreeSitterNode,
    properties: string[],
    exports: StructuralAnalysis["exports"],
  ): void {
    const nameNode = node.childForFieldName("name");
    if (!nameNode) return;

    properties.push(nameNode.text);

    if (hasModifier(node, "public")) {
      exports.push({
        name: nameNode.text,
        lineNumber: node.startPosition.row + 1,
      });
    }
  }

  private extractField(
    node: TreeSitterNode,
    properties: string[],
    exports: StructuralAnalysis["exports"],
  ): void {
    // field_declaration -> variable_declaration -> variable_declarator(s)
    const varDecl = findChild(node, "variable_declaration");
    if (!varDecl) return;

    const declarators = findChildren(varDecl, "variable_declarator");
    for (const decl of declarators) {
      // variable_declarator's first child is the identifier
      const nameNode = findChild(decl, "identifier");
      if (nameNode) {
        properties.push(nameNode.text);

        if (hasModifier(node, "public")) {
          exports.push({
            name: nameNode.text,
            lineNumber: node.startPosition.row + 1,
          });
        }
      }
    }
  }
}

extractStructure(rootNode: TreeSitterNode): StructuralAnalysis {
    const functions: StructuralAnalysis["functions"] = [];
    const classes: StructuralAnalysis["classes"] = [];
    const imports: StructuralAnalysis["imports"] = [];
    const exports: StructuralAnalysis["exports"] = [];

    this.walkTopLevel(rootNode, functions, classes, imports, exports);

    return { functions, classes, imports, exports };
  }

extractCallGraph(rootNode: TreeSitterNode): CallGraphEntry[] {
    const entries: CallGraphEntry[] = [];
    const functionStack: string[] = [];

    const walkForCalls = (node: TreeSitterNode) => {
      let pushedName = false;

      // Track entering method/constructor declarations
      if (
        node.type === "method_declaration" ||
        node.type === "constructor_declaration"
      ) {
        const nameNode = node.childForFieldName("name");
        if (nameNode) {
          functionStack.push(nameNode.text);
          pushedName = true;
        }
      }

      // Extract method invocations: e.g. FetchFromDb(limit), Console.WriteLine(msg)
      if (node.type === "invocation_expression") {
        if (functionStack.length > 0) {
          const callee = extractInvocationName(node);
          if (callee) {
            entries.push({
              caller: functionStack[functionStack.length - 1],
              callee,
              lineNumber: node.startPosition.row + 1,
            });
          }
        }
      }

      // Extract object creation: e.g. new Foo()
      if (node.type === "object_creation_expression") {
        if (functionStack.length > 0) {
          // The type is the child after `new` — can be identifier or generic_name
          const typeNode = findChild(node, "identifier") ?? findChild(node, "generic_name");
          if (typeNode) {
            entries.push({
              caller: functionStack[functionStack.length - 1],
              callee: `new ${typeNode.text}`,
              lineNumber: node.startPosition.row + 1,
            });
          }
        }
      }

      for (let i = 0; i < node.childCount; i++) {
        const child = node.child(i);
        if (child) walkForCalls(child);
      }

      if (pushedName) {
        functionStack.pop();
      }
    };

    walkForCalls(rootNode);

    return entries;
  }

private walkTopLevel(
    node: TreeSitterNode,
    functions: StructuralAnalysis["functions"],
    classes: StructuralAnalysis["classes"],
    imports: StructuralAnalysis["imports"],
    exports: StructuralAnalysis["exports"],
  ): void {
    for (let i = 0; i < node.childCount; i++) {
      const child = node.child(i);
      if (!child) continue;

      switch (child.type) {
        case "using_directive":
          this.extractUsing(child, imports);
          break;

        case "namespace_declaration":
          // Recurse into namespace body (declaration_list)
          this.walkNamespaceBody(child, functions, classes, imports, exports);
          break;

        case "file_scoped_namespace_declaration":
          // File-scoped namespace: declarations are siblings at the root,
          // not children of this node. Nothing to recurse into.
          break;

        case "class_declaration":
        case "record_declaration":
        case "struct_declaration":
          this.extractClass(child, functions, classes, exports);
          break;

        case "interface_declaration":
          this.extractInterface(child, functions, classes, exports);
          break;
      }
    }
  }

private walkNamespaceBody(
    nsNode: TreeSitterNode,
    functions: StructuralAnalysis["functions"],
    classes: StructuralAnalysis["classes"],
    imports: StructuralAnalysis["imports"],
    exports: StructuralAnalysis["exports"],
  ): void {
    const body = nsNode.childForFieldName("body");
    if (!body) return;

    for (let i = 0; i < body.childCount; i++) {
      const child = body.child(i);
      if (!child) continue;

      switch (child.type) {
        case "class_declaration":
        case "record_declaration":
        case "struct_declaration":
          this.extractClass(child, functions, classes, exports);
          break;

        case "interface_declaration":
          this.extractInterface(child, functions, classes, exports);
          break;

        case "namespace_declaration":
          // Nested namespaces
          this.walkNamespaceBody(child, functions, classes, imports, exports);
          break;
      }
    }
  }

private extractUsing(
    node: TreeSitterNode,
    imports: StructuralAnalysis["imports"],
  ): void {
    const source = extractUsingSource(node);
    if (!source) return;

    imports.push({
      source,
      specifiers: [lastComponent(source)],
      lineNumber: node.startPosition.row + 1,
    });
  }

private extractClass(
    node: TreeSitterNode,
    functions: StructuralAnalysis["functions"],
    classes: StructuralAnalysis["classes"],
    exports: StructuralAnalysis["exports"],
  ): void {
    const nameNode = node.childForFieldName("name");
    if (!nameNode) return;

    const methods: string[] = [];
    const properties: string[] = [];

    const body = node.childForFieldName("body");
    if (body) {
      this.extractClassBodyMembers(body, methods, properties, functions, exports);
    }

    classes.push({
      name: nameNode.text,
      lineRange: [
        node.startPosition.row + 1,
        node.endPosition.row + 1,
      ],
      methods,
      properties,
    });

    if (hasModifier(node, "public")) {
      exports.push({
        name: nameNode.text,
        lineNumber: node.startPosition.row + 1,
      });
    }
  }

private extractInterface(
    node: TreeSitterNode,
    functions: StructuralAnalysis["functions"],
    classes: StructuralAnalysis["classes"],
    exports: StructuralAnalysis["exports"],
  ): void {
    const nameNode = node.childForFieldName("name");
    if (!nameNode) return;

    const methods: string[] = [];
    const properties: string[] = [];

    const body = node.childForFieldName("body");
    if (body) {
      // Interface body contains method_declaration nodes (signatures without bodies)
      const methodNodes = findChildren(body, "method_declaration");
      for (const methodNode of methodNodes) {
        const methNameNode = methodNode.childForFieldName("name");
        if (methNameNode) {
          methods.push(methNameNode.text);
        }
      }

      // Interface can contain property_declaration nodes
      const propNodes = findChildren(body, "property_declaration");
      for (const propNode of propNodes) {
        const propNameNode = propNode.childForFieldName("name");
        if (propNameNode) {
          properties.push(propNameNode.text);
        }
      }
    }

    classes.push({
      name: nameNode.text,
      lineRange: [
        node.startPosition.row + 1,
        node.endPosition.row + 1,
      ],
      methods,
      properties,
    });

    if (hasModifier(node, "public")) {
      exports.push({
        name: nameNode.text,
        lineNumber: node.startPosition.row + 1,
      });
    }
  }

private extractClassBodyMembers(
    body: TreeSitterNode,
    methods: string[],
    properties: string[],
    functions: StructuralAnalysis["functions"],
    exports: StructuralAnalysis["exports"],
  ): void {
    for (let i = 0; i < body.childCount; i++) {
      const child = body.child(i);
      if (!child) continue;

      switch (child.type) {
        case "method_declaration":
          this.extractMethod(child, methods, functions, exports);
          break;

        case "constructor_declaration":
          this.extractConstructor(child, methods, functions, exports);
          break;

        case "property_declaration":
          this.extractProperty(child, properties, exports);
          break;

        case "field_declaration":
          this.extractField(child, properties, exports);
          break;
      }
    }
  }

private extractMethod(
    node: TreeSitterNode,
    methods: string[],
    functions: StructuralAnalysis["functions"],
    exports: StructuralAnalysis["exports"],
  ): void {
    const nameNode = node.childForFieldName("name");
    if (!nameNode) return;

    const paramsNode = node.childForFieldName("parameters");
    const params = extractParams(paramsNode ?? null);
    const returnType = extractReturnType(node);

    methods.push(nameNode.text);

    functions.push({
      name: nameNode.text,
      lineRange: [
        node.startPosition.row + 1,
        node.endPosition.row + 1,
      ],
      params,
      returnType,
    });

    if (hasModifier(node, "public")) {
      exports.push({
        name: nameNode.text,
        lineNumber: node.startPosition.row + 1,
      });
    }
  }

private extractConstructor(
    node: TreeSitterNode,
    methods: string[],
    functions: StructuralAnalysis["functions"],
    exports: StructuralAnalysis["exports"],
  ): void {
    const nameNode = node.childForFieldName("name");
    if (!nameNode) return;

    const paramsNode = node.childForFieldName("parameters");
    const params = extractParams(paramsNode ?? null);

    methods.push(nameNode.text);

    functions.push({
      name: nameNode.text,
      lineRange: [
        node.startPosition.row + 1,
        node.endPosition.row + 1,
      ],
      params,
      // Constructors have no return type
    });

    if (hasModifier(node, "public")) {
      exports.push({
        name: nameNode.text,
        lineNumber: node.startPosition.row + 1,
      });
    }
  }

private extractProperty(
    node: TreeSitterNode,
    properties: string[],
    exports: StructuralAnalysis["exports"],
  ): void {
    const nameNode = node.childForFieldName("name");
    if (!nameNode) return;

    properties.push(nameNode.text);

    if (hasModifier(node, "public")) {
      exports.push({
        name: nameNode.text,
        lineNumber: node.startPosition.row + 1,
      });
    }
  }

private extractField(
    node: TreeSitterNode,
    properties: string[],
    exports: StructuralAnalysis["exports"],
  ): void {
    // field_declaration -> variable_declaration -> variable_declarator(s)
    const varDecl = findChild(node, "variable_declaration");
    if (!varDecl) return;

    const declarators = findChildren(varDecl, "variable_declarator");
    for (const decl of declarators) {
      // variable_declarator's first child is the identifier
      const nameNode = findChild(decl, "identifier");
      if (nameNode) {
        properties.push(nameNode.text);

        if (hasModifier(node, "public")) {
          exports.push({
            name: nameNode.text,
            lineNumber: node.startPosition.row + 1,
          });
        }
      }
    }
  }

function isExported(name: string): boolean {
  return !name.startsWith("_");
}

function extractFunctionName(sig: TreeSitterNode): string | null {
  const id = findChild(sig, "identifier");
  return id ? id.text : null;
}

function extractParamName(paramNode: TreeSitterNode): string | null {
  // Direct identifier child wins (regular `Type name` parameter).
  const direct = findChild(paramNode, "identifier");
  if (direct) return direct.text;

  // Nested wrappers — pick the last identifier we can find inside.
  for (let i = 0; i < paramNode.childCount; i++) {
    const child = paramNode.child(i);
    if (!child) continue;
    if (child.type === "constructor_param" || child.type === "super_formal_parameter") {
      let last: string | null = null;
      for (let j = 0; j < child.childCount; j++) {
        const inner = child.child(j);
        if (inner && inner.type === "identifier") last = inner.text;
      }
      if (last) return last;
    }
  }
  return null;
}

function extractParams(sig: TreeSitterNode): string[] {
  const params: string[] = [];
  const list = findChild(sig, "formal_parameter_list");
  if (!list) return params;
  for (let i = 0; i < list.childCount; i++) {
    const child = list.child(i);
    if (!child) continue;
    if (child.type === "formal_parameter") {
      const name = extractParamName(child);
      if (name) params.push(name);
    } else if (child.type === "optional_formal_parameters") {
      // Walk one level deeper — children are again `formal_parameter`.
      for (const sub of findChildren(child, "formal_parameter")) {
        const name = extractParamName(sub);
        if (name) params.push(name);
      }
    }
  }
  return params;
}

function extractReturnType(sig: TreeSitterNode): string | undefined {
  const parts: string[] = [];
  for (let i = 0; i < sig.childCount; i++) {
    const child = sig.child(i);
    if (!child || !child.isNamed) continue;
    if (
      child.type === "identifier" ||
      child.type === "formal_parameter_list" ||
      child.type === "type_parameters"
    ) {
      // Reached the function NAME (`identifier`), the parameter list, or the
      // generic-parameter list (`type_parameters` is the function's own
      // generics, e.g. `<T>` in `T fn<T>(T x)`). Anything we passed before
      // this point WAS the return type; if we hit this stop without having
      // collected anything, the function has no declared return type.
      break;
    }
    parts.push(child.text);
  }
  return parts.length > 0 ? parts.join("") : undefined;
}

function pushMethod(
  declNode: TreeSitterNode,
  sig: TreeSitterNode,
  name: string,
  methods: string[],
  functions: StructuralAnalysis["functions"],
  exports: StructuralAnalysis["exports"],
): void {
  methods.push(name);
  functions.push({
    name,
    lineRange: [declNode.startPosition.row + 1, declNode.endPosition.row + 1],
    params: extractParams(sig),
    returnType: extractReturnType(sig),
  });
  if (isExported(name)) {
    exports.push({ name, lineNumber: declNode.startPosition.row + 1 });
  }
}

function uriText(uriNode: TreeSitterNode): string | null {
  const lit = findChild(uriNode, "string_literal");
  if (!lit) return null;
  return getStringValue(lit);
}

function constructorName(sig: TreeSitterNode): string | null {
  const ids = findChildren(sig, "identifier");
  if (ids.length === 0) return null;
  if (ids.length === 1) return ids[0].text;
  return `${ids[0].text}.${ids[1].text}`;
}

function collectClassBody(
  body: TreeSitterNode,
  methods: string[],
  properties: string[],
  functions: StructuralAnalysis["functions"],
  exports: StructuralAnalysis["exports"],
): void {
  for (let i = 0; i < body.childCount; i++) {
    const member = body.child(i);
    if (!member) continue;

    if (member.type === "method_signature") {
      // Factory constructor lives inside method_signature.
      const factory = findChild(member, "factory_constructor_signature");
      if (factory) {
        const name = constructorName(factory);
        if (name) {
          pushMethod(member, factory, name, methods, functions, exports);
        }
        continue;
      }
      // Getter (`int get value`) — wrapped in method_signature with a
      // sibling function_body. The name is the only identifier in getter_signature.
      const getter = findChild(member, "getter_signature");
      if (getter) {
        const name = extractFunctionName(getter);
        if (name) pushMethod(member, getter, name, methods, functions, exports);
        continue;
      }
      // Setter (`set value(int x)`) — wrapped in method_signature with a
      // sibling function_body. The first identifier is the name; the
      // formal_parameter_list holds the assigned value.
      const setter = findChild(member, "setter_signature");
      if (setter) {
        const name = extractFunctionName(setter);
        if (name) pushMethod(member, setter, name, methods, functions, exports);
        continue;
      }
      // Concrete method: `method_signature > function_signature`.
      const inner = findChild(member, "function_signature");
      if (!inner) continue;
      const name = extractFunctionName(inner);
      if (!name) continue;
      pushMethod(member, inner, name, methods, functions, exports);
    } else if (member.type === "declaration") {
      // Regular constructor: `declaration > constructor_signature`.
      const ctor = findChild(member, "constructor_signature");
      if (ctor) {
        const name = constructorName(ctor);
        if (name) {
          pushMethod(member, ctor, name, methods, functions, exports);
        }
        continue;
      }
      // Abstract getter (`int get area;`) — `declaration > getter_signature`.
      const absGetter = findChild(member, "getter_signature");
      if (absGetter) {
        const name = extractFunctionName(absGetter);
        if (name) pushMethod(member, absGetter, name, methods, functions, exports);
        continue;
      }
      // Abstract setter (`set width(int w);`) — `declaration > setter_signature`.
      const absSetter = findChild(member, "setter_signature");
      if (absSetter) {
        const name = extractFunctionName(absSetter);
        if (name) pushMethod(member, absSetter, name, methods, functions, exports);
        continue;
      }
      // Abstract method declarations (e.g. `double area();`) appear as
      // `declaration > function_signature` — not wrapped in `method_signature`.
      const fnSig = findChild(member, "function_signature");
      if (fnSig) {
        const name = extractFunctionName(fnSig);
        if (name) {
          pushMethod(member, fnSig, name, methods, functions, exports);
        }
        continue;
      }
      // Field declaration — surface initialized_identifier names as properties.
      // Comma-lists like `int a, b, c;` produce multiple initialized_identifier
      // children inside a single initialized_identifier_list.
      const list = findChild(member, "initialized_identifier_list");
      if (!list) continue;
      for (const init of findChildren(list, "initialized_identifier")) {
        const id = findChild(init, "identifier");
        if (id) properties.push(id.text);
      }
    }
  }
}

class DartExtractor implements LanguageExtractor {
  readonly languageIds = ["dart"];

  extractStructure(rootNode: TreeSitterNode): StructuralAnalysis {
    const functions: StructuralAnalysis["functions"] = [];
    const classes: StructuralAnalysis["classes"] = [];
    const imports: StructuralAnalysis["imports"] = [];
    const exports: StructuralAnalysis["exports"] = [];

    for (let i = 0; i < rootNode.childCount; i++) {
      const node = rootNode.child(i);
      if (!node) continue;

      switch (node.type) {
        case "function_signature":
          this.extractTopLevelFunction(node, functions, exports);
          break;
        case "class_definition":
          this.extractClassLikeDeclaration(node, "class_body", classes, functions, exports);
          break;
        case "mixin_declaration":
          this.extractClassLikeDeclaration(node, "class_body", classes, functions, exports);
          break;
        case "extension_declaration":
          this.extractExtensionDeclaration(node, classes, functions, exports);
          break;
        case "enum_declaration":
          this.extractEnumDeclaration(node, classes, exports);
          break;
        case "import_or_export":
          this.extractImportOrExport(node, imports, exports);
          break;
      }
    }

    return { functions, classes, imports, exports };
  }

  // ---- Private helpers ----

  private extractTopLevelFunction(
    sig: TreeSitterNode,
    functions: StructuralAnalysis["functions"],
    exports: StructuralAnalysis["exports"],
  ): void {
    const name = extractFunctionName(sig);
    if (!name) return;
    functions.push({
      name,
      lineRange: [sig.startPosition.row + 1, sig.endPosition.row + 1],
      params: extractParams(sig),
      returnType: extractReturnType(sig),
    });
    if (isExported(name)) {
      exports.push({ name, lineNumber: sig.startPosition.row + 1 });
    }
  }

  /**
   * Extract a class-like declaration that uses a `class_body`-shaped member
   * container. Used by `class_definition`, `mixin_declaration`, and (Task 8)
   * `extension_declaration`. The only difference between these shapes is the
   * body's node type name, which is passed in via `bodyNodeType`.
   *
   * When `nameOverride` is provided, it is used as the entry's name instead of
   * looking up a leading `identifier` child — used by anonymous extensions,
   * which have no name in the source.
   */
  private extractClassLikeDeclaration(
    declNode: TreeSitterNode,
    bodyNodeType: string,
    classes: StructuralAnalysis["classes"],
    functions: StructuralAnalysis["functions"],
    exports: StructuralAnalysis["exports"],
    nameOverride?: string,
  ): void {
    let name: string;
    if (nameOverride !== undefined) {
      name = nameOverride;
    } else {
      const nameNode = findChild(declNode, "identifier");
      if (!nameNode) return;
      name = nameNode.text;
    }

    const methods: string[] = [];
    const properties: string[] = [];

    const body = findChild(declNode, bodyNodeType);
    if (body) {
      collectClassBody(body, methods, properties, functions, exports);
    }

    classes.push({
      name,
      lineRange: [declNode.startPosition.row + 1, declNode.endPosition.row + 1],
      methods,
      properties,
    });

    if (isExported(name)) {
      exports.push({ name, lineNumber: declNode.startPosition.row + 1 });
    }
  }

  private extractExtensionDeclaration(
    declNode: TreeSitterNode,
    classes: StructuralAnalysis["classes"],
    functions: StructuralAnalysis["functions"],
    exports: StructuralAnalysis["exports"],
  ): void {
    // Named extension — extractClassLikeDeclaration finds the leading identifier itself.
    const idNode = findChild(declNode, "identifier");
    if (idNode) {
      this.extractClassLikeDeclaration(
        declNode,
        "extension_body",
        classes,
        functions,
        exports,
      );
      return;
    }

    // Anonymous extension — no `identifier` child. The on-type is the first
    // `type_identifier`. Name the entry "on <TargetType>" so the graph
    // builder doesn't drop it for having an empty name.
    const onType = findChild(declNode, "type_identifier");
    if (!onType) return;
    this.extractClassLikeDeclaration(
      declNode,
      "extension_body",
      classes,
      functions,
      exports,
      `on ${onType.text}`,
    );
  }

  private extractEnumDeclaration(
    declNode: TreeSitterNode,
    classes: StructuralAnalysis["classes"],
    exports: StructuralAnalysis["exports"],
  ): void {
    const nameNode = findChild(declNode, "identifier");
    if (!nameNode) return;
    const name = nameNode.text;

    const properties: string[] = [];
    const body = findChild(declNode, "enum_body");
    if (body) {
      for (const k of findChildren(body, "enum_constant")) {
        const id = findChild(k, "identifier");
        if (id) properties.push(id.text);
      }
    }

    classes.push({
      name,
      lineRange: [declNode.startPosition.row + 1, declNode.endPosition.row + 1],
      methods: [],
      properties,
    });

    if (isExported(name)) {
      exports.push({ name, lineNumber: declNode.startPosition.row + 1 });
    }
  }

  private extractImportOrExport(
    declNode: TreeSitterNode,
    imports: StructuralAnalysis["imports"],
    exports: StructuralAnalysis["exports"],
  ): void {
    const libImport = findChild(declNode, "library_import");
    if (libImport) {
      this.extractLibraryImport(libImport, imports);
      return;
    }
    const libExport = findChild(declNode, "library_export");
    if (libExport) {
      this.extractLibraryExport(libExport, declNode, exports);
    }
  }

  private extractLibraryImport(
    libImport: TreeSitterNode,
    imports: StructuralAnalysis["imports"],
  ): void {
    const spec = findChild(libImport, "import_specification");
    if (!spec) return;

    const configurable = findChild(spec, "configurable_uri");
    const uri = configurable ? findChild(configurable, "uri") : null;
    if (!uri) return;
    const source = uriText(uri);
    if (!source) return;

    const specifiers: string[] = [];

    // Combinators come in two flavours:
    //   show Bar, Baz  → leading keyword "show", names are specifiers
    //   hide Qux       → leading keyword "hide", names are excluded — skip
    const combinators = findChildren(spec, "combinator");
    for (const c of combinators) {
      // Inspect the first child to determine show vs hide. The keyword is an
      // unnamed token; use `child()` not `namedChild()`.
      const first = c.child(0);
      if (first && first.type === "hide") continue;
      for (const id of findChildren(c, "identifier")) {
        specifiers.push(id.text);
      }
    }

    // `as Foo` → direct `identifier` child of import_specification.
    // Only treat as alias when there were no `show`/`hide` specifiers.
    const asId = findChild(spec, "identifier");
    if (asId && specifiers.length === 0) {
      specifiers.push(asId.text);
    }

    imports.push({
      source,
      specifiers,
      lineNumber: libImport.startPosition.row + 1,
    });
  }

  /**
   * Extract an `export` directive's URI into `exports[]`.
   *
   * Takes both `libExport` (the `library_export` node containing the URI)
   * and `outerNode` (the wrapping `import_or_export` node). The line number
   * uses `outerNode.startPosition` because `library_export` may start one
   * child deeper than the `export` keyword, while `import_or_export` is
   * guaranteed to start at the keyword.
   */
  private extractLibraryExport(
    libExport: TreeSitterNode,
    outerNode: TreeSitterNode,
    exports: StructuralAnalysis["exports"],
  ): void {
    const configurable = findChild(libExport, "configurable_uri");
    const uri = configurable ? findChild(configurable, "uri") : null;
    if (!uri) return;
    const source = uriText(uri);
    if (!source) return;
    exports.push({
      name: source,
      lineNumber: outerNode.startPosition.row + 1,
    });
  }

  extractCallGraph(rootNode: TreeSitterNode): CallGraphEntry[] {
    const entries: CallGraphEntry[] = [];
    const functionStack: string[] = [];

    /**
     * Walk a single node, recursing into its children. Detects call sites
     * (selector nodes containing argument_part) and records them against the
     * current function on the stack.
     *
     * In Dart's AST, `function_signature` and `function_body` are SIBLINGS
     * within their parent (program, class_body, etc.), NOT parent/child. This
     * differs from Kotlin where `function_declaration` wraps both signature and
     * body. We handle this by scanning siblings at the parent level:
     * `walkSiblings` iterates the children of a container, remembers the name
     * from each `function_signature` / `method_signature`, and pushes it onto
     * the stack only for the duration of the following `function_body`.
     */
    const walkNode = (node: TreeSitterNode) => {
      if (
        node.type === "selector" &&
        findChild(node, "argument_part") &&
        functionStack.length > 0
      ) {
        // A call site: selector containing argument_part.
        const callee = this.extractCalleeName(node);
        if (callee) {
          entries.push({
            caller: functionStack[functionStack.length - 1],
            callee,
            lineNumber: node.startPosition.row + 1,
          });
        }
      }

      // Constructor-call shapes that bypass the `selector > argument_part`
      // pattern:
      //   const Foo(...)  → `const_object_expression { const_builtin, type_identifier, arguments }`
      //   new Foo(...)    → `new_expression { (unnamed `new`), type_identifier, arguments }`
      // Both are extremely common in Flutter widget trees; without this branch
      // the construction edge would be silently dropped. The callee is the
      // `type_identifier` child.
      if (
        (node.type === "const_object_expression" ||
          node.type === "new_expression") &&
        functionStack.length > 0
      ) {
        const typeNode = findChild(node, "type_identifier");
        if (typeNode) {
          entries.push({
            caller: functionStack[functionStack.length - 1],
            callee: typeNode.text,
            lineNumber: node.startPosition.row + 1,
          });
        }
      }

      walkSiblings(node);
    };

    /**
     * Iterate a node's children, pairing each function_signature /
     * method_signature with its subsequent function_body sibling.
     */
    const walkSiblings = (parent: TreeSitterNode) => {
      let pendingName: string | null = null;

      for (let i = 0; i < parent.childCount; i++) {
        const child = parent.child(i);
        if (!child) continue;

        if (child.type === "function_signature") {
          pendingName = extractFunctionName(child);
          // Recurse into signature (no calls expected, but stay complete).
          walkSiblings(child);
        } else if (child.type === "method_signature") {
          // method_signature wraps one of:
          //   function_signature           → normal method
          //   getter_signature             → getter (with body)
          //   setter_signature             → setter (with body)
          //   constructor_signature        → constructor (with body)
          //   factory_constructor_signature → factory (with body)
          // All five carry the name as their first `identifier` child (factory
          // ctors carry two — class + named — handled by `constructorName`).
          // Without this dispatch, ctor/factory/getter/setter bodies were
          // walked with an empty functionStack and their internal calls were
          // dropped from the graph.
          const fn =
            findChild(child, "function_signature") ??
            findChild(child, "getter_signature") ??
            findChild(child, "setter_signature");
          if (fn) {
            pendingName = extractFunctionName(fn);
          } else {
            const ctor =
              findChild(child, "constructor_signature") ??
              findChild(child, "factory_constructor_signature");
            if (ctor) pendingName = constructorName(ctor);
          }
          walkSiblings(child);
        } else if (child.type === "function_body") {
          // Consume pendingName: push for the duration of this body.
          const pushed = pendingName !== null;
          if (pendingName) {
            functionStack.push(pendingName);
            pendingName = null;
          }
          walkNode(child);
          if (pushed) functionStack.pop();
        } else {
          // For every other node (including selector nodes at this level),
          // do NOT clear pendingName — anonymous tokens (`;`, `{`, etc.)
          // appear between the signature and body and must not reset the
          // pending name.
          walkNode(child);
        }
      }
    };

    walkSiblings(rootNode);
    return entries;
  }

  /**
   * Find the callee name for a `selector` node that contains an
   * `argument_part`. Look at the parent's children:
   *   - Bare call `foo(...)`: the previous sibling is an `identifier`.
   *   - Method call `target.foo(...)`: the previous sibling is itself a
   *     `selector` wrapping `unconditional_assignable_selector` with the
   *     method-name `identifier`.
   *
   * Probe finding (2026-06-13): the plan's claimed AST shapes match exactly.
   *   - Bare call:   return_statement > identifier[helper] + selector(argument_part)
   *   - Method call: expression_statement > string_literal + selector(unconditional_assignable_selector > identifier[toUpperCase]) + selector(argument_part)
   * The plan claimed `expression_statement` as parent for bare calls but the
   * actual parent for `return helper()` is `return_statement`. This does not
   * affect the strategy since we only look at the preceding sibling, not the
   * parent type.
   *
   * IMPORTANT: web-tree-sitter returns a NEW wrapper object each time `.child(i)`
   * is called — node identity (`===`) does NOT work for sibling lookup. We
   * compare by `startIndex` (byte offset) which is stable and unique per node.
   */
  private extractCalleeName(callSelector: TreeSitterNode): string | null {
    const parent = callSelector.parent;
    if (!parent) return null;

    // Find this selector's index in the parent using startIndex (not ===).
    let myIdx = -1;
    for (let i = 0; i < parent.childCount; i++) {
      const c = parent.child(i);
      if (c && c.startIndex === callSelector.startIndex) {
        myIdx = i;
        break;
      }
    }
    if (myIdx <= 0) return null;

    const prev = parent.child(myIdx - 1);
    if (!prev) return null;

    if (prev.type === "identifier") return prev.text;

    if (prev.type === "selector") {
      // Method call shape: previous selector wraps unconditional_assignable_selector.
      const inner = findChild(prev, "unconditional_assignable_selector");
      if (inner) {
        // Pick the LAST identifier inside the inner selector — that's the
        // method name (earlier identifiers, if any, are receiver fragments).
        let last: string | null = null;
        for (let i = 0; i < inner.childCount; i++) {
          const child = inner.child(i);
          if (child && child.type === "identifier") last = child.text;
        }
        return last;
      }
    }

    return null;
  }
}

extractStructure(rootNode: TreeSitterNode): StructuralAnalysis {
    const functions: StructuralAnalysis["functions"] = [];
    const classes: StructuralAnalysis["classes"] = [];
    const imports: StructuralAnalysis["imports"] = [];
    const exports: StructuralAnalysis["exports"] = [];

    for (let i = 0; i < rootNode.childCount; i++) {
      const node = rootNode.child(i);
      if (!node) continue;

      switch (node.type) {
        case "function_signature":
          this.extractTopLevelFunction(node, functions, exports);
          break;
        case "class_definition":
          this.extractClassLikeDeclaration(node, "class_body", classes, functions, exports);
          break;
        case "mixin_declaration":
          this.extractClassLikeDeclaration(node, "class_body", classes, functions, exports);
          break;
        case "extension_declaration":
          this.extractExtensionDeclaration(node, classes, functions, exports);
          break;
        case "enum_declaration":
          this.extractEnumDeclaration(node, classes, exports);
          break;
        case "import_or_export":
          this.extractImportOrExport(node, imports, exports);
          break;
      }
    }

    return { functions, classes, imports, exports };
  }

private extractTopLevelFunction(
    sig: TreeSitterNode,
    functions: StructuralAnalysis["functions"],
    exports: StructuralAnalysis["exports"],
  ): void {
    const name = extractFunctionName(sig);
    if (!name) return;
    functions.push({
      name,
      lineRange: [sig.startPosition.row + 1, sig.endPosition.row + 1],
      params: extractParams(sig),
      returnType: extractReturnType(sig),
    });
    if (isExported(name)) {
      exports.push({ name, lineNumber: sig.startPosition.row + 1 });
    }
  }

private extractClassLikeDeclaration(
    declNode: TreeSitterNode,
    bodyNodeType: string,
    classes: StructuralAnalysis["classes"],
    functions: StructuralAnalysis["functions"],
    exports: StructuralAnalysis["exports"],
    nameOverride?: string,
  ): void {
    let name: string;
    if (nameOverride !== undefined) {
      name = nameOverride;
    } else {
      const nameNode = findChild(declNode, "identifier");
      if (!nameNode) return;
      name = nameNode.text;
    }

    const methods: string[] = [];
    const properties: string[] = [];

    const body = findChild(declNode, bodyNodeType);
    if (body) {
      collectClassBody(body, methods, properties, functions, exports);
    }

    classes.push({
      name,
      lineRange: [declNode.startPosition.row + 1, declNode.endPosition.row + 1],
      methods,
      properties,
    });

    if (isExported(name)) {
      exports.push({ name, lineNumber: declNode.startPosition.row + 1 });
    }
  }

private extractExtensionDeclaration(
    declNode: TreeSitterNode,
    classes: StructuralAnalysis["classes"],
    functions: StructuralAnalysis["functions"],
    exports: StructuralAnalysis["exports"],
  ): void {
    // Named extension — extractClassLikeDeclaration finds the leading identifier itself.
    const idNode = findChild(declNode, "identifier");
    if (idNode) {
      this.extractClassLikeDeclaration(
        declNode,
        "extension_body",
        classes,
        functions,
        exports,
      );
      return;
    }

    // Anonymous extension — no `identifier` child. The on-type is the first
    // `type_identifier`. Name the entry "on <TargetType>" so the graph
    // builder doesn't drop it for having an empty name.
    const onType = findChild(declNode, "type_identifier");
    if (!onType) return;
    this.extractClassLikeDeclaration(
      declNode,
      "extension_body",
      classes,
      functions,
      exports,
      `on ${onType.text}`,
    );
  }

private extractEnumDeclaration(
    declNode: TreeSitterNode,
    classes: StructuralAnalysis["classes"],
    exports: StructuralAnalysis["exports"],
  ): void {
    const nameNode = findChild(declNode, "identifier");
    if (!nameNode) return;
    const name = nameNode.text;

    const properties: string[] = [];
    const body = findChild(declNode, "enum_body");
    if (body) {
      for (const k of findChildren(body, "enum_constant")) {
        const id = findChild(k, "identifier");
        if (id) properties.push(id.text);
      }
    }

    classes.push({
      name,
      lineRange: [declNode.startPosition.row + 1, declNode.endPosition.row + 1],
      methods: [],
      properties,
    });

    if (isExported(name)) {
      exports.push({ name, lineNumber: declNode.startPosition.row + 1 });
    }
  }

private extractImportOrExport(
    declNode: TreeSitterNode,
    imports: StructuralAnalysis["imports"],
    exports: StructuralAnalysis["exports"],
  ): void {
    const libImport = findChild(declNode, "library_import");
    if (libImport) {
      this.extractLibraryImport(libImport, imports);
      return;
    }
    const libExport = findChild(declNode, "library_export");
    if (libExport) {
      this.extractLibraryExport(libExport, declNode, exports);
    }
  }

private extractLibraryImport(
    libImport: TreeSitterNode,
    imports: StructuralAnalysis["imports"],
  ): void {
    const spec = findChild(libImport, "import_specification");
    if (!spec) return;

    const configurable = findChild(spec, "configurable_uri");
    const uri = configurable ? findChild(configurable, "uri") : null;
    if (!uri) return;
    const source = uriText(uri);
    if (!source) return;

    const specifiers: string[] = [];

    // Combinators come in two flavours:
    //   show Bar, Baz  → leading keyword "show", names are specifiers
    //   hide Qux       → leading keyword "hide", names are excluded — skip
    const combinators = findChildren(spec, "combinator");
    for (const c of combinators) {
      // Inspect the first child to determine show vs hide. The keyword is an
      // unnamed token; use `child()` not `namedChild()`.
      const first = c.child(0);
      if (first && first.type === "hide") continue;
      for (const id of findChildren(c, "identifier")) {
        specifiers.push(id.text);
      }
    }

    // `as Foo` → direct `identifier` child of import_specification.
    // Only treat as alias when there were no `show`/`hide` specifiers.
    const asId = findChild(spec, "identifier");
    if (asId && specifiers.length === 0) {
      specifiers.push(asId.text);
    }

    imports.push({
      source,
      specifiers,
      lineNumber: libImport.startPosition.row + 1,
    });
  }

private extractLibraryExport(
    libExport: TreeSitterNode,
    outerNode: TreeSitterNode,
    exports: StructuralAnalysis["exports"],
  ): void {
    const configurable = findChild(libExport, "configurable_uri");
    const uri = configurable ? findChild(configurable, "uri") : null;
    if (!uri) return;
    const source = uriText(uri);
    if (!source) return;
    exports.push({
      name: source,
      lineNumber: outerNode.startPosition.row + 1,
    });
  }

extractCallGraph(rootNode: TreeSitterNode): CallGraphEntry[] {
    const entries: CallGraphEntry[] = [];
    const functionStack: string[] = [];

    /**
     * Walk a single node, recursing into its children. Detects call sites
     * (selector nodes containing argument_part) and records them against the
     * current function on the stack.
     *
     * In Dart's AST, `function_signature` and `function_body` are SIBLINGS
     * within their parent (program, class_body, etc.), NOT parent/child. This
     * differs from Kotlin where `function_declaration` wraps both signature and
     * body. We handle this by scanning siblings at the parent level:
     * `walkSiblings` iterates the children of a container, remembers the name
     * from each `function_signature` / `method_signature`, and pushes it onto
     * the stack only for the duration of the following `function_body`.
     */
    const walkNode = (node: TreeSitterNode) => {
      if (
        node.type === "selector" &&
        findChild(node, "argument_part") &&
        functionStack.length > 0
      ) {
        // A call site: selector containing argument_part.
        const callee = this.extractCalleeName(node);
        if (callee) {
          entries.push({
            caller: functionStack[functionStack.length - 1],
            callee,
            lineNumber: node.startPosition.row + 1,
          });
        }
      }

      // Constructor-call shapes that bypass the `selector > argument_part`
      // pattern:
      //   const Foo(...)  → `const_object_expression { const_builtin, type_identifier, arguments }`
      //   new Foo(...)    → `new_expression { (unnamed `new`), type_identifier, arguments }`
      // Both are extremely common in Flutter widget trees; without this branch
      // the construction edge would be silently dropped. The callee is the
      // `type_identifier` child.
      if (
        (node.type === "const_object_expression" ||
          node.type === "new_expression") &&
        functionStack.length > 0
      ) {
        const typeNode = findChild(node, "type_identifier");
        if (typeNode) {
          entries.push({
            caller: functionStack[functionStack.length - 1],
            callee: typeNode.text,
            lineNumber: node.startPosition.row + 1,
          });
        }
      }

      walkSiblings(node);
    };

    /**
     * Iterate a node's children, pairing each function_signature /
     * method_signature with its subsequent function_body sibling.
     */
    const walkSiblings = (parent: TreeSitterNode) => {
      let pendingName: string | null = null;

      for (let i = 0; i < parent.childCount; i++) {
        const child = parent.child(i);
        if (!child) continue;

        if (child.type === "function_signature") {
          pendingName = extractFunctionName(child);
          // Recurse into signature (no calls expected, but stay complete).
          walkSiblings(child);
        } else if (child.type === "method_signature") {
          // method_signature wraps one of:
          //   function_signature           → normal method
          //   getter_signature             → getter (with body)
          //   setter_signature             → setter (with body)
          //   constructor_signature        → constructor (with body)
          //   factory_constructor_signature → factory (with body)
          // All five carry the name as their first `identifier` child (factory
          // ctors carry two — class + named — handled by `constructorName`).
          // Without this dispatch, ctor/factory/getter/setter bodies were
          // walked with an empty functionStack and their internal calls were
          // dropped from the graph.
          const fn =
            findChild(child, "function_signature") ??
            findChild(child, "getter_signature") ??
            findChild(child, "setter_signature");
          if (fn) {
            pendingName = extractFunctionName(fn);
          } else {
            const ctor =
              findChild(child, "constructor_signature") ??
              findChild(child, "factory_constructor_signature");
            if (ctor) pendingName = constructorName(ctor);
          }
          walkSiblings(child);
        } else if (child.type === "function_body") {
          // Consume pendingName: push for the duration of this body.
          const pushed = pendingName !== null;
          if (pendingName) {
            functionStack.push(pendingName);
            pendingName = null;
          }
          walkNode(child);
          if (pushed) functionStack.pop();
        } else {
          // For every other node (including selector nodes at this level),
          // do NOT clear pendingName — anonymous tokens (`;`, `{`, etc.)
          // appear between the signature and body and must not reset the
          // pending name.
          walkNode(child);
        }
      }
    };

    walkSiblings(rootNode);
    return entries;
  }

private extractCalleeName(callSelector: TreeSitterNode): string | null {
    const parent = callSelector.parent;
    if (!parent) return null;

    // Find this selector's index in the parent using startIndex (not ===).
    let myIdx = -1;
    for (let i = 0; i < parent.childCount; i++) {
      const c = parent.child(i);
      if (c && c.startIndex === callSelector.startIndex) {
        myIdx = i;
        break;
      }
    }
    if (myIdx <= 0) return null;

    const prev = parent.child(myIdx - 1);
    if (!prev) return null;

    if (prev.type === "identifier") return prev.text;

    if (prev.type === "selector") {
      // Method call shape: previous selector wraps unconditional_assignable_selector.
      const inner = findChild(prev, "unconditional_assignable_selector");
      if (inner) {
        // Pick the LAST identifier inside the inner selector — that's the
        // method name (earlier identifiers, if any, are receiver fragments).
        let last: string | null = null;
        for (let i = 0; i < inner.childCount; i++) {
          const child = inner.child(i);
          if (child && child.type === "identifier") last = child.text;
        }
        return last;
      }
    }

    return null;
  }

function extractParams(paramsNode: TreeSitterNode | null): string[] {
  if (!paramsNode) return [];
  const params: string[] = [];

  const declarations = findChildren(paramsNode, "parameter_declaration");
  for (const decl of declarations) {
    // A parameter_declaration can have multiple name identifiers sharing
    // a type, e.g. `a, b int`.  Collect all identifiers.
    for (let i = 0; i < decl.childCount; i++) {
      const child = decl.child(i);
      if (child && child.type === "identifier") {
        params.push(child.text);
      }
    }
  }

  return params;
}

function extractResultType(node: TreeSitterNode): string | undefined {
  const result = node.childForFieldName("result");
  if (!result) return undefined;
  return result.text;
}

function extractReceiverType(receiverNode: TreeSitterNode): string | undefined {
  const decl = findChild(receiverNode, "parameter_declaration");
  if (!decl) return undefined;

  // Follow only the receiver's base type, never its generic type arguments.
  let type = decl.childForFieldName("type");
  if (type?.type === "pointer_type") type = type.namedChildren[0] ?? null;
  if (type?.type === "generic_type") type = type.childForFieldName("type");
  if (type?.type === "type_identifier") {
    return type.text;
  }
  return undefined;
}

function isExported(name: string): boolean {
  if (name.length === 0) return false;
  const first = name.charCodeAt(0);
  return first >= 65 && first <= 90; // A-Z
}

class GoExtractor implements LanguageExtractor {
  readonly languageIds = ["go"];

  extractStructure(rootNode: TreeSitterNode): StructuralAnalysis {
    const functions: StructuralAnalysis["functions"] = [];
    const classes: StructuralAnalysis["classes"] = [];
    const imports: StructuralAnalysis["imports"] = [];
    const exports: StructuralAnalysis["exports"] = [];

    // Track methods per receiver type so we can attach them to structs
    const methodsByReceiver = new Map<string, string[]>();

    for (let i = 0; i < rootNode.childCount; i++) {
      const node = rootNode.child(i);
      if (!node) continue;

      switch (node.type) {
        case "function_declaration":
          this.extractFunction(node, functions, exports);
          break;

        case "method_declaration":
          this.extractMethod(node, functions, exports, methodsByReceiver);
          break;

        case "type_declaration":
          this.extractTypeDeclaration(node, classes, exports);
          break;

        case "import_declaration":
          this.extractImportDeclaration(node, imports);
          break;
      }
    }

    // Attach collected methods to their receiver structs/interfaces
    for (const cls of classes) {
      const methods = methodsByReceiver.get(cls.name);
      if (methods) {
        cls.methods.push(...methods);
      }
    }

    return { functions, classes, imports, exports };
  }

  extractCallGraph(rootNode: TreeSitterNode): CallGraphEntry[] {
    const entries: CallGraphEntry[] = [];
    const functionStack: string[] = [];

    const walkForCalls = (node: TreeSitterNode) => {
      let pushedName = false;

      // Track entering function/method declarations
      if (node.type === "function_declaration") {
        const nameNode = node.childForFieldName("name");
        if (nameNode) {
          functionStack.push(nameNode.text);
          pushedName = true;
        }
      } else if (node.type === "method_declaration") {
        const nameNode = node.childForFieldName("name");
        if (nameNode) {
          functionStack.push(nameNode.text);
          pushedName = true;
        }
      }

      // Extract call expressions
      if (node.type === "call_expression") {
        const calleeNode = node.childForFieldName("function");
        if (calleeNode && functionStack.length > 0) {
          entries.push({
            caller: functionStack[functionStack.length - 1],
            callee: calleeNode.text,
            lineNumber: node.startPosition.row + 1,
          });
        }
      }

      for (let i = 0; i < node.childCount; i++) {
        const child = node.child(i);
        if (child) walkForCalls(child);
      }

      if (pushedName) {
        functionStack.pop();
      }
    };

    walkForCalls(rootNode);

    return entries;
  }

  // ---- Private helpers ----

  private extractFunction(
    node: TreeSitterNode,
    functions: StructuralAnalysis["functions"],
    exports: StructuralAnalysis["exports"],
  ): void {
    const nameNode = node.childForFieldName("name");
    if (!nameNode) return;

    const paramsNode = node.childForFieldName("parameters");
    const params = extractParams(paramsNode ?? null);
    const returnType = extractResultType(node);

    functions.push({
      name: nameNode.text,
      owner: "",
      lineRange: [
        node.startPosition.row + 1,
        node.endPosition.row + 1,
      ],
      params,
      returnType,
    });

    if (isExported(nameNode.text)) {
      exports.push({
        name: nameNode.text,
        lineNumber: node.startPosition.row + 1,
      });
    }
  }

  private extractMethod(
    node: TreeSitterNode,
    functions: StructuralAnalysis["functions"],
    exports: StructuralAnalysis["exports"],
    methodsByReceiver: Map<string, string[]>,
  ): void {
    const nameNode = node.childForFieldName("name");
    if (!nameNode) return;

    const paramsNode = node.childForFieldName("parameters");
    const params = extractParams(paramsNode ?? null);
    const returnType = extractResultType(node);
    const receiverNode = node.childForFieldName("receiver");
    const receiverType = receiverNode ? extractReceiverType(receiverNode) : undefined;

    functions.push({
      name: nameNode.text,
      owner: receiverType ?? null,
      lineRange: [
        node.startPosition.row + 1,
        node.endPosition.row + 1,
      ],
      params,
      returnType,
    });

    // Track receiver type for struct association
    if (receiverType) {
      if (!methodsByReceiver.has(receiverType)) {
        methodsByReceiver.set(receiverType, []);
      }
      methodsByReceiver.get(receiverType)!.push(nameNode.text);
    }

    if (isExported(nameNode.text)) {
      exports.push({
        name: nameNode.text,
        lineNumber: node.startPosition.row + 1,
      });
    }
  }

  private extractTypeDeclaration(
    node: TreeSitterNode,
    classes: StructuralAnalysis["classes"],
    exports: StructuralAnalysis["exports"],
  ): void {
    const typeSpec = findChild(node, "type_spec");
    if (!typeSpec) return;

    const nameNode = typeSpec.childForFieldName("name");
    const typeNode = typeSpec.childForFieldName("type");
    if (!nameNode || !typeNode) return;

    if (typeNode.type === "struct_type") {
      this.extractStruct(node, nameNode, typeNode, classes, exports);
    } else if (typeNode.type === "interface_type") {
      this.extractInterface(node, nameNode, typeNode, classes, exports);
    }
  }

  private extractStruct(
    declNode: TreeSitterNode,
    nameNode: TreeSitterNode,
    structNode: TreeSitterNode,
    classes: StructuralAnalysis["classes"],
    exports: StructuralAnalysis["exports"],
  ): void {
    const properties: string[] = [];

    const fieldList = findChild(structNode, "field_declaration_list");
    if (fieldList) {
      const fields = findChildren(fieldList, "field_declaration");
      for (const field of fields) {
        // A field_declaration can have multiple names: `X, Y int`
        for (let i = 0; i < field.childCount; i++) {
          const child = field.child(i);
          if (child && child.type === "field_identifier") {
            properties.push(child.text);
          }
        }
      }
    }

    classes.push({
      name: nameNode.text,
      lineRange: [
        declNode.startPosition.row + 1,
        declNode.endPosition.row + 1,
      ],
      methods: [], // Methods are attached later from methodsByReceiver
      properties,
    });

    if (isExported(nameNode.text)) {
      exports.push({
        name: nameNode.text,
        lineNumber: declNode.startPosition.row + 1,
      });
    }
  }

  private extractInterface(
    declNode: TreeSitterNode,
    nameNode: TreeSitterNode,
    interfaceNode: TreeSitterNode,
    classes: StructuralAnalysis["classes"],
    exports: StructuralAnalysis["exports"],
  ): void {
    const methods: string[] = [];

    const methodElems = findChildren(interfaceNode, "method_elem");
    for (const elem of methodElems) {
      const methName = elem.childForFieldName("name");
      if (methName) {
        methods.push(methName.text);
      }
    }

    classes.push({
      name: nameNode.text,
      lineRange: [
        declNode.startPosition.row + 1,
        declNode.endPosition.row + 1,
      ],
      methods,
      properties: [], // Interfaces have no properties
    });

    if (isExported(nameNode.text)) {
      exports.push({
        name: nameNode.text,
        lineNumber: declNode.startPosition.row + 1,
      });
    }
  }

  private extractImportDeclaration(
    node: TreeSitterNode,
    imports: StructuralAnalysis["imports"],
  ): void {
    // Grouped imports: import ( ... )
    const specList = findChild(node, "import_spec_list");
    if (specList) {
      const specs = findChildren(specList, "import_spec");
      for (const spec of specs) {
        this.extractImportSpec(spec, imports);
      }
    } else {
      // Single import: import "fmt"
      const spec = findChild(node, "import_spec");
      if (spec) {
        this.extractImportSpec(spec, imports);
      }
    }
  }

  private extractImportSpec(
    spec: TreeSitterNode,
    imports: StructuralAnalysis["imports"],
  ): void {
    const pathNode = spec.childForFieldName("path");
    if (!pathNode) return;

    // Extract unquoted path
    const pathContent = findChild(pathNode, "interpreted_string_literal_content");
    const source = pathContent ? pathContent.text : pathNode.text.replace(/^"|"$/g, "");

    // Determine the specifier: alias if present, otherwise last path component
    const nameNode = spec.childForFieldName("name");
    let specifier: string;
    if (nameNode) {
      specifier = nameNode.text;
    } else {
      // Use last path component, e.g. "net/http" -> "http"
      const parts = source.split("/");
      specifier = parts[parts.length - 1];
    }

    imports.push({
      source,
      specifiers: [specifier],
      lineNumber: spec.startPosition.row + 1,
    });
  }
}

extractStructure(rootNode: TreeSitterNode): StructuralAnalysis {
