    const definitions: DefinitionInfo[] = [];
    const lines = content.split("\n");
    for (let i = 0; i < lines.length; i++) {
      const line = lines[i].trim();
      if (line.startsWith("#") || line === "") continue;
      const match = line.match(/^([A-Za-z_][A-Za-z0-9_]*)=/);
      if (match) {
        definitions.push({
          name: match[1],
          kind: "variable",
          lineRange: [i + 1, i + 1],
          fields: [],
        });
      }
    }
    return definitions;
  }
