function unescaped(text: string): boolean {
  return !text.includes("\\") && !text.includes("`") && !text.startsWith("@")
    && !text.startsWith("r#") && text.normalize("NFKC") === text;
}

function literal(node: Node | null | undefined): string | null {
  if (!node) return null;
  if (node.type === "simple_symbol") return unescaped(node.text) ? node.text.slice(1) : null;
  if (["string", "delimited_symbol"].includes(node.type)) {
    if (!unescaped(node.text) || node.namedChildren.some(child =>
      !["string_fragment", "string_content", "string_start", "string_end"].includes(child.type)
      || child.namedChildren.length > 0)) return null;
    return node.namedChildren.filter(child => ["string_fragment", "string_content"].includes(child.type))
      .map(child => child.text).join("");
  }
  return null;
}

function identifier(node: Node | null | undefined): string | null {
  return node && ["identifier", "property_identifier", "private_property_identifier", "field_identifier", "type_identifier", "constant",
    "simple_identifier", "scope_resolution", "scoped_type_identifier", "qualified_identifier",
    "shorthand_property_identifier", "shorthand_property_identifier_pattern"].includes(node.type)
    && unescaped(node.text) ? node.text : null;
}

function declarationName(node: Node | null | undefined): string | null {
  return identifier(node) ?? literal(node);
}

function declarationKey(node: Node): Node | null {
  return node.childForFieldName("name")
    ?? (node.type === "field_definition" ? node.childForFieldName("property") : null);
}

function unwrap(node: Node | null): Node | null {
  while (node && ["parenthesized_expression", "parenthesized_statements"].includes(node.type)
    && node.namedChildren.length === 1) node = node.namedChildren[0];
  return node;
}

function classExpression(node: Node): boolean {
  return node.type === "class" && node.childForFieldName("body")?.type === "class_body";
}

function declarationGap(node: Node, scope: SymbolScope, receiver: SymbolScope): SymbolEvidenceEntry | null {
  const range: [number, number] = [node.startPosition.row + 1, node.endPosition.row + 1];
  // TypeScript parameter properties have both parameter-binding and class-
  // member roles. Their declaration target is the indexed receiver scope.
  if (["required_parameter", "optional_parameter"].includes(node.type)
    && node.children.some(child => ["accessibility_modifier", "readonly", "override_modifier", "override"].includes(child.type))) {
    return { kind: "callable", scope: receiver,
      name: declarationName(node.childForFieldName("pattern") ?? declarationKey(node)), lineRange: range,
      reason: "Parameter-property callability is not covered by structural extraction" };
  }
  if (OPAQUE_DECLARATIONS.has(node.type)) return { kind: null, scope: UNKNOWN_SCOPE, name: null,
    lineRange: range, reason: `Declaration expansion is not verified: ${node.type}` };
  const name = declarationKey(node);
  if (!name || HANDLED_NAMES.has(node.type) || NON_DECLARATION_NAMES.has(node.type)) return null;
  return { kind: null, scope, name: declarationName(name), lineRange: range,
    reason: `Declaration surface is not covered: ${node.type}` };
}

interface SymbolEvidenceEntry {
  kind: "callable" | "class" | null;
  scope: SymbolScope;
  name: string | null;
  nameSuffix?: string;
  lineRange: [number, number];
  reason: string;
}

interface SymbolEvidence {
  version: 2;
  effects: SymbolEvidenceEntry[];
  functions: Array<{ name: string; scope: SymbolScope; lineRange: [number, number] }>;
  classes: Array<{ name: string; scope: SymbolScope; lineRange: [number, number] }>;
  coverage: { profile: "structural-declarations-v1"; gaps: SymbolEvidenceEntry[] };
}

function member(node: Node | null): { object: Node | null; name: string | null } | null {
  node = unwrap(node);
  if (!node) return null;
  if (["member_expression", "attribute"].includes(node.type)) {
    return { object: node.childForFieldName("object"), name: identifier(node.childForFieldName("property")
      ?? node.childForFieldName("attribute")) };
  }
  if (["subscript_expression", "subscript"].includes(node.type)) {
    return { object: node.childForFieldName("object") ?? node.childForFieldName("value"),
      name: literal(node.childForFieldName("index") ?? node.childForFieldName("subscript")) };
  }
  return null;
}

function collectSymbolEvidence(root: Node, structure: StructuralAnalysis, language: string): SymbolEvidence {
  const effects: SymbolEvidenceEntry[] = [];
  const isJS = ["javascript", "typescript", "tsx"].includes(language);
  const isRuby = language === "ruby";
  const isPython = language === "python";
  const scopes = buildSymbolScopes(root, language);
  const coverage: SymbolEvidence["coverage"] = { profile: "structural-declarations-v1", gaps: [] };
  const classes: SymbolEvidence["classes"] = [];
  const functions: SymbolEvidence["functions"] = [];
  const matchedFunctions = new Set<number>();
  const classScopes = new Map<string, SymbolScope>();
  const handledReferences = new Set<number>();
  const add = (node: Node, scope: SymbolScope, name: string | null, reason: string,
    kind: SymbolEvidenceEntry["kind"] = "callable", nameSuffix?: string) => {
    effects.push({ kind, scope, name, ...(nameSuffix ? { nameSuffix } : {}),
      lineRange: [node.startPosition.row + 1, node.endPosition.row + 1], reason });
  };
  const cover = (node: Node, scope: SymbolScope, name: string | null, reason: string,
    kind: SymbolEvidenceEntry["kind"] = "callable") => {
    coverage.gaps.push({ kind, scope, name, lineRange: [node.startPosition.row + 1, node.endPosition.row + 1], reason });
  };
  const consume = (node: Node | null) => {
    if (!node) return;
    const pending = [node];
    while (pending.length) { const item = pending.pop()!; handledReferences.add(item.id); pending.push(...item.namedChildren); }
  };
  const targetOwner = (target: Node | null, context: Node): SymbolScope => {
    target = unwrap(target);
    const name = identifier(target);
    if (name) return scopes.reference(target!, name);
    if (target && ["self", "this"].includes(target.text)) {
      const receiver = scopes.receiver(context);
      return receiver.kind === "file" ? UNKNOWN_SCOPE : receiver;
    }
    const access = member(target);
    if (access?.name === "prototype" || access?.name === "__dict__") return targetOwner(access.object, context);
    return UNKNOWN_SCOPE;
  };
  const objectKeys = (object: Node | undefined, owner: SymbolScope, context: Node) => {
    if (!object || !["object", "dictionary"].includes(object.type)) {
      add(context, owner, null, "Unresolved property descriptor collection", null); return;
    }
    for (const field of object.namedChildren) {
      const key = field.childForFieldName("key") ?? field.childForFieldName("name")
        ?? (field.type === "shorthand_property_identifier" ? field : null);
      const computed = key?.type === "computed_property_name";
      add(field, owner, computed ? literal(key.namedChildren[0]) : declarationName(key), "Runtime property definition", null);
    }
  };
  const visit = (node: Node) => {
    const owner = scopes.declaration(node);
    const gap = declarationGap(node, owner, scopes.receiver(node));
    if (gap) coverage.gaps.push(gap);
    const declared = declarationKey(node);
    const declaredName = declared?.type === "computed_property_name" ? literal(declared.namedChildren[0]) : declarationName(declared);
    const objectMethod = isJS && node.type === "method_definition" && node.parent?.type === "object";
    const localDeclaration = owner.kind === "local";
    if (node !== root && CLASS_NODES.has(node.type)) {
      const target = scopes.classTarget(node);
      const classScope = target.kind === "class" ? FILE_SCOPE : target;
      const className = classExpression(node) ? target.kind === "class" ? target.name : null : declaredName;
      if (declaredName) {
        classScopes.set(JSON.stringify([declaredName, node.startPosition.row + 1, node.endPosition.row + 1]), target);
        classes.push({ name: declaredName, scope: classScope, lineRange: [node.startPosition.row + 1, node.endPosition.row + 1] });
      }
      if (!structure.classes.some(cls => cls.name === className && cls.lineRange[0] === node.startPosition.row + 1
        && cls.lineRange[1] === node.endPosition.row + 1)) {
        coverage.gaps.push({ kind: "class", scope: classScope, name: className,
          lineRange: [node.startPosition.row + 1, node.endPosition.row + 1], reason: "Class declaration is not covered by structural extraction" });
      }
    }
    if (FUNCTION_NODES.has(node.type) && !objectMethod) {
      const valueFunction = ["arrow_function", "function_expression", "generator_function", "lambda"].includes(node.type);
      const name = valueFunction ? identifier(node.parent?.childForFieldName("name")) : declaredName;
      const matches = structure.functions.map((fn, index) => ({ fn, index })).filter(({ fn }) => fn.owner === undefined
        && (fn.name === name || node.type === "singleton_method" && fn.name === `self.${name}`)
        && fn.lineRange[0] === node.startPosition.row + 1 && fn.lineRange[1] === node.endPosition.row + 1);
      if (matches.length) {
        let scope = owner;
        if (node.type === "singleton_method") {
          const receiver = node.childForFieldName("object") ?? node.childForFieldName("receiver");
          scope = receiver?.text === "self" ? owner : targetOwner(receiver, node);
        }
        functions.push({ name: matches[0].fn.name, scope,
          lineRange: [node.startPosition.row + 1, node.endPosition.row + 1] });
        for (const { index } of matches) matchedFunctions.add(index);
      }
      const detailed = structure.functions.some(fn => fn.owner !== undefined
        && fn.lineRange[0] === node.startPosition.row + 1 && fn.lineRange[1] === node.endPosition.row + 1);
      const inventoriedMethod = name !== null && owner.kind === "class"
        && structure.classes.some(cls => cls.name === owner.name && cls.methods.includes(name));
      if ((!valueFunction || name !== null) && !matches.length && !detailed && !inventoriedMethod) coverage.gaps.push({ kind: "callable", scope: owner, name,
        lineRange: [node.startPosition.row + 1, node.endPosition.row + 1], reason: "Callable declaration is not covered by structural extraction" });
    }
    // Escaped/opaque declaration spellings cannot establish absence. Ordinary
    // identifiers, references and string literals do not imply declarations.
    if (declared && !objectMethod && !localDeclaration && !classExpression(node)
      && (CLASS_NODES.has(node.type) || FUNCTION_NODES.has(node.type))
      && declaredName === null) {
      cover(declared, CLASS_NODES.has(node.type) ? FILE_SCOPE : owner, null, "Unresolved declaration name",
        CLASS_NODES.has(node.type) ? "class" : "callable");
    }
    if (owner.kind === "unknown" && !objectMethod && !localDeclaration && FUNCTION_NODES.has(node.type) && declaredName !== null) {
      cover(node, UNKNOWN_SCOPE, declaredName, "Unresolved declaring type");
    }
    if (isJS && !objectMethod && node.type === "method_definition" && declared?.type === "string") {
      cover(node, owner, literal(declared), "Quoted method declaration");
    }
    if (isJS && ["public_field_definition", "field_definition", "method_signature", "abstract_method_signature"].includes(node.type)) {
      const name = declarationKey(node);
      cover(node, owner, name?.type === "computed_property_name" ? literal(name.namedChildren[0]) : declarationName(name),
        "Class member not verified by structural extraction");
    }
    if (isJS && node.type === "computed_property_name" && node.parent?.type === "method_definition"
      && node.parent.parent?.type === "class_body") {
      cover(node, owner, literal(node.namedChildren[0]), "Computed method declaration");
    }
    if ((isJS || isPython) && ["assignment_expression", "augmented_assignment_expression", "assignment", "augmented_assignment",
      "variable_declarator"].includes(node.type)) {
      const target = node.childForFieldName("left") ?? node.childForFieldName("name");
      const inspect = (part: Node) => {
        const access = member(part);
        if (access) {
          if (isJS && access.name === "prototype") objectKeys(node.childForFieldName("right")
            ?? node.childForFieldName("value") ?? undefined, targetOwner(access.object, node), node);
          else add(part, targetOwner(access.object, node), access.name, "Property assignment", null);
        } else if (identifier(part) && !localDeclaration) {
          add(part, owner, identifier(part), "Binding assignment", null);
        } else if (["object_pattern", "array_pattern", "pair_pattern", "parenthesized_expression"].includes(part.type)) {
          const value = part.childForFieldName("value");
          for (const child of value ? [value] : part.namedChildren) inspect(child);
        }
      };
      if (target) inspect(target);
    }
    if (isRuby && node.type === "alias" && declared?.type !== "global_variable") {
      add(node, owner, declarationName(declared), "Ruby alias declaration");
    }
    if (isRuby && node.type === "call") {
      const methodNode = node.childForFieldName("method");
      const method = methodNode?.text;
      const args = [...(node.childForFieldName("arguments")?.namedChildren ?? [])];
      const receiver = node.childForFieldName("receiver");
      const boundOwner = !receiver || receiver.text === "self" ? scopes.receiver(node) : targetOwner(receiver, node);
      if (method && RUBY_INSTALLERS.has(method)) {
        consume(methodNode);
        if (ACCESSORS.has(method)) {
          let writer = ["attr_writer", "attr_accessor"].includes(method);
          if (method === "attr" && args.length === 2 && ["true", "false"].includes(args[1].type)) writer = args.pop()!.type === "true";
          for (const arg of args) {
            const name = literal(arg);
            if (method !== "attr_writer") add(arg, boundOwner, name, "Ruby accessor reader");
            if (writer) add(arg, boundOwner, name === null ? null : `${name}=`, "Ruby accessor writer", "callable", name === null ? "=" : undefined);
          }
        } else if (args.length) {
          const name = literal(args[0]);
          add(node, boundOwner, method === "define_singleton_method" && name !== null ? `self.${name}` : name, "Ruby method installer");
        }
      } else if (method && ["method", "public_method", "instance_method", "public_instance_method", "singleton_method"].includes(method) && args.length) {
        const name = literal(args[0]);
        if (name === null || RUBY_INSTALLERS.has(name)) add(node, method.includes("instance_method") ? UNKNOWN_SCOPE : boundOwner, null, "Indirect method installer");
      } else if (method && EVALUATORS.has(method)) {
        consume(methodNode); add(node, UNKNOWN_SCOPE, null, "Dynamic dispatch or code evaluation", null);
      }
    }
    if ((isJS && node.type === "call_expression") || (isPython && node.type === "call")) {
      const callee = unwrap(node.childForFieldName("function"));
      const access = member(callee);
      const method = access?.name ?? identifier(callee);
      const args = node.childForFieldName("arguments")?.namedChildren ?? [];
      const directInstaller = method && (isJS ? JS_INSTALLERS.has(method) || method === "set"
        && access?.object?.text === "Reflect" : PY_INSTALLERS.has(method));
      if (directInstaller) {
        consume(callee);
        const namespace = access?.object;
        const standard = isJS
          ? namespace && scopes.unbound(namespace, namespace.text)
            && (namespace.text === "Object" && ["defineProperty", "defineProperties"].includes(method)
              || namespace.text === "Reflect" && ["defineProperty", "set"].includes(method))
          : !access && method === "setattr" && scopes.unbound(callee!, method);
        if (!standard) add(node, UNKNOWN_SCOPE, null, "Runtime installer identity is unresolved", null);
        else if (method === "defineProperties") objectKeys(args[1], targetOwner(args[0] ?? null, node), node);
        else add(node, targetOwner(args[0] ?? null, node), literal(args[1]), "Runtime property definition", null);
      } else if (isJS && method === "assign" && access?.object?.text === "Object") {
        consume(callee);
        if (!scopes.unbound(access.object, "Object")) add(node, UNKNOWN_SCOPE, null, "Runtime installer identity is unresolved", null);
        else for (const arg of args.slice(1)) objectKeys(arg, targetOwner(args[0] ?? null, node), node);
      } else if (method && ((isJS ? JS_EVALUATORS : PY_EVALUATORS).has(method) || isPython && method === "type" && args.length >= 3)) {
        consume(callee); add(node, UNKNOWN_SCOPE, null, "Dynamic code or class evaluation", null);
      } else if (access && access.name === null) {
        consume(callee); add(node, UNKNOWN_SCOPE, null, "Computed callee may select a runtime installer", null);
      }
    }
    // References to installers may escape through aliases. Direct calls were
    // already consumed and retain their more precise target/name evidence.
    if (!handledReferences.has(node.id)) {
      const access = member(node);
      if (isJS && access?.object?.text === "Reflect" && scopes.unbound(access.object, "Reflect")
        && ["get", "has", "ownKeys", "getOwnPropertyDescriptor", "getPrototypeOf", "isExtensible"].includes(access.name ?? "")) {
        consume(node);
      } else if (isJS && access && (access.name !== null && JS_INSTALLERS.has(access.name)
        || access.object?.text === "Object" && (access.name === "assign" || access.name === null))) {
        consume(node); add(node, UNKNOWN_SCOPE, null, "Aliased property installer", null);
      } else if (isPython && access?.name === "__dict__") {
        consume(node); add(node, targetOwner(access.object, node), null, "Indirect attribute dictionary", null);
      } else if (node.type === "identifier" && node.parent?.childForFieldName("name")?.id !== node.id
        && (isJS && (JS_INSTALLERS.has(node.text) || node.text === "Reflect" || JS_EVALUATORS.has(node.text))
        || isPython && (PY_INSTALLERS.has(node.text) || ["exec", "eval", "globals", "locals", "vars"].includes(node.text)))) {
        add(node, UNKNOWN_SCOPE, null, "Aliased runtime installer or evaluation", null);
      }
    }
    for (const child of node.namedChildren) visit(child);
  };
  visit(root);
  if (!isJS && !isRuby && !isPython) {
    // A callable may become an unextracted function-valued field. Retain the
    // extractor's property inventory as scoped possibilities, without treating
    // arbitrary identifier/string uses as declarations.
    for (const cls of structure.classes) for (const name of cls.properties) {
      coverage.gaps.push({ kind: "callable", scope: classScopes.get(JSON.stringify([cls.name, ...cls.lineRange])) ?? UNKNOWN_SCOPE,
        name: unescaped(name) ? name : null, lineRange: cls.lineRange, reason: "Property callability is not structurally verified" });
    }
  }
  for (const [index, fn] of structure.functions.entries()) {
    if (fn.owner === undefined && !matchedFunctions.has(index)) functions.push({ name: fn.name, scope: UNKNOWN_SCOPE, lineRange: fn.lineRange });
  }
  for (const fn of [...structure.functions.filter(fn => fn.owner !== undefined).map(fn => ({ ...fn, scope: namedScope(fn.owner ?? null) })), ...functions]) {
    // The C++ extractor can leave nested qualification in the function name
    // (N::A::run -> owner N, name A::run). That decomposition cannot prove
    // an inline A.run disappeared when its definition moved out of class.
    if (language === "cpp" && fn.name.includes("::")) coverage.gaps.push({ kind: "callable", scope: UNKNOWN_SCOPE,
      name: fn.name.split("::").at(-1) ?? null, lineRange: fn.lineRange,
      reason: "Unverified compound C++ qualification" });
    if (fn.scope.kind === "unknown") coverage.gaps.push({ kind: "callable", scope: UNKNOWN_SCOPE, name: fn.name,
      lineRange: fn.lineRange, reason: "Unresolved source receiver ownership" });
  }
  if (!COVERAGE_LANGUAGES.has(language)) {
    coverage.gaps.push({ kind: null, scope: UNKNOWN_SCOPE, name: null, lineRange: [1, root.endPosition.row + 1],
      reason: "This language has no verified declaration-coverage adapter" });
  }
  return { version: 2, effects, functions, classes, coverage };
}

function inspect(code: string, check: (nodes: Node[], scopes: ReturnType<typeof buildSymbolScopes>) => void) {
  const parser = new Parser(); parser.setLanguage(language);
  const tree = parser.parse(code)!;
  try {
    expect(tree.rootNode.hasError).toBe(false);
    const nodes: Node[] = [];
    const visit = (node: Node) => { nodes.push(node); node.namedChildren.forEach(visit); };
    visit(tree.rootNode);
    check(nodes, buildSymbolScopes(tree.rootNode, "typescript"));
  } finally { tree.delete(); parser.delete(); }
}

type SymbolScope =
  | { kind: "file" }
  | { kind: "class"; name: string }
  | { kind: "local"; id: number }
  | { kind: "unknown" };

function namedScope(name: string | null): SymbolScope {
  return name === null ? UNKNOWN_SCOPE : name === "" ? FILE_SCOPE : { kind: "class", name };
}

interface Scope {
  id: number;
  parent: Scope | null;
  kind: "root" | "class" | "function" | "block" | "namespace";
  receiver: Target;
  localDeclarations: boolean;
  bindings: Map<string, Map<number, Target>>;
  unknownBindings: boolean;
}

function buildSymbolScopes(root: Node, language: string) {
  const isJS = ["javascript", "typescript", "tsx"].includes(language);
  const facts = new Map<number, Facts>();
  const assignments: Array<{ node: Node; scope: Scope }> = [];
  const makeScope = (node: Node, parent: Scope | null, kind: Scope["kind"], receiver: Target,
    localDeclarations: boolean): Scope => ({ id: node.id, parent, kind, receiver, localDeclarations,
    bindings: new Map(), unknownBindings: false });
  const global = makeScope(root, null, "root", fileTarget, false);
  const local = (node: Node): Target => fixed({ kind: "local", id: node.id });
  const declarationScope = (scope: Scope): Target => scope.localDeclarations ? fixed({ kind: "local", id: scope.id }) : scope.receiver;
  const classBinding = (name: string | null, scope: Scope, node: Node): Target =>
    scope.kind === "root" ? fixed(namedScope(name)) : scope.kind === "namespace" ? unknownTarget : local(node);
  const targets = (node: Node | null): Array<string | null> => {
    if (!node) return [];
    const name = identifier(node);
    if (name) return [name];
    if (["identifier", "constant", "shorthand_property_identifier_pattern"].includes(node.type)) return [null];
    const pattern = node.childForFieldName("pattern") ?? node.childForFieldName("name")
      ?? node.childForFieldName("left") ?? node.childForFieldName("value");
    if (pattern) return targets(pattern);
    if (["formal_parameters", "parameters", "method_parameters", "object_pattern", "array_pattern", "pattern_list",
      "rest_pattern", "rest_parameter", "splat_parameter", "list_splat_pattern", "dictionary_splat_pattern"].includes(node.type)) return node.namedChildren.flatMap(targets);
    if (node.type === "typed_parameter") return targets(node.namedChildren[0] ?? null);
    return [];
  };
  const bind = (scope: Scope, name: string | null, node: Node, target: Target) => {
    if (name === null) { scope.unknownBindings = true; return; }
    if (!scope.bindings.has(name)) scope.bindings.set(name, new Map());
    scope.bindings.get(name)!.set(node.id, target);
  };
  const lookup = (start: Scope, name: string): { scope: Scope; values: Map<number, Target> } | null | undefined => {
    let scope: Scope | null = start;
    while (scope) {
      if (scope.unknownBindings) return null;
      const values = scope.bindings.get(name);
      if (values) return { scope, values };
      const leavingFunction = scope.kind === "function";
      scope = scope.parent;
      if (language === "python" && leavingFunction) while (scope?.kind === "class") scope = scope.parent;
    }
    return undefined;
  };
  const assignmentTarget = (node: Node | null, scope: Scope): Target => () => {
    const name = identifier(node);
    if (!name) return UNKNOWN_SCOPE;
    const found = lookup(scope, name);
    if (found === null) return UNKNOWN_SCOPE;
    return classBinding(name, found?.scope ?? global, node!)();
  };
  const scan = (node: Node, enclosing: Scope, region?: ValueRegion) => {
    let scope = enclosing;
    const declaration = declarationScope(enclosing);
    const isClass = node !== root && CLASS_NODES.has(node.type);
    const isFunction = FUNCTION_NODES.has(node.type);
    const expression = isJS && classExpression(node);
    const nameNode = node.childForFieldName("name");
    const name = identifier(nameNode);
    let classTarget: Target | undefined;
    if (isClass) {
      classTarget = expression ? !region ? local(node) : () => {
        const target = region.target();
        return region.directValue === node.id || target.kind === "local" ? target : UNKNOWN_SCOPE;
      } : classBinding(name, enclosing, node);
      // Expression names are internal; declaration names bind outside as well.
      if (!expression && nameNode) bind(enclosing, name, node, classTarget);
      scope = makeScope(node, enclosing, "class", classTarget, false);
      if (isJS && nameNode) bind(scope, name, node, classTarget);
    } else if (node.type === "singleton_class") {
      scope = makeScope(node, enclosing, "class", unknownTarget, false);
    } else if (isFunction) {
      const declaresBinding = !METHODS.has(node.type) && !["function_expression", "generator_function", "arrow_function", "lambda"].includes(node.type);
      if (declaresBinding && nameNode) bind(enclosing, name, node, unknownTarget);
      const receiver = isJS && !METHODS.has(node.type) && node.type !== "arrow_function" ? unknownTarget : enclosing.receiver;
      scope = makeScope(node, enclosing, "function", receiver, true);
      if (["function_expression", "generator_function"].includes(node.type) && nameNode) bind(scope, name, node, unknownTarget);
      for (const parameter of targets(node.childForFieldName("parameters"))) bind(scope, parameter, node, unknownTarget);
    } else if (isJS && ["statement_block", "class_static_block", "for_statement", "for_in_statement", "catch_clause", "switch_statement", "with_statement"].includes(node.type)) {
      scope = makeScope(node, enclosing, "block", enclosing.receiver, true);
    } else if (["namespace_definition", "namespace_declaration"].includes(node.type)) {
      scope = makeScope(node, enclosing, "namespace", unknownTarget, false);
    }
    facts.set(node.id, { scope, declaration, receiver: enclosing.receiver, classTarget });
    if (isJS && node.type === "with_statement") scope.unknownBindings = true;
    if (isJS && node.type === "catch_clause") {
      for (const parameter of targets(node.childForFieldName("parameter"))) bind(scope, parameter, node, unknownTarget);
    }
    if (node.type === "for_in_statement" || language === "python" && node.type === "for_statement") {
      for (const target of targets(node.childForFieldName("left"))) {
        const declared = node.childForFieldName("kind");
        const found = target && lookup(enclosing, target);
        const destination = !isJS ? scope : declared?.text === "var" ? enclosing
          : declared ? scope : found ? found.scope : global;
        bind(destination, target, node, unknownTarget);
      }
    }
    if (language === "python" && node.type === "as_pattern") {
      const alias = node.childForFieldName("alias");
      for (const part of alias?.namedChildren ?? []) if (part.type === "identifier") bind(scope, identifier(part), node, unknownTarget);
    }

    let value: Node | null = null;
    let valueRegion: ValueRegion | undefined;
    if (node.type === "variable_declarator") {
      let destination = scope;
      if (node.parent?.type === "variable_declaration") while (destination.kind === "block" && destination.parent) destination = destination.parent;
      value = node.childForFieldName("value");
      const direct = unwrap(value);
      const bindingName = identifier(node.childForFieldName("name"));
      const target = bindingName ? classBinding(bindingName, destination, node) : unknownTarget;
      for (const binding of targets(node.childForFieldName("name"))) bind(destination, binding, node,
        direct && classExpression(direct) && binding === bindingName ? target : unknownTarget);
      if (value) valueRegion = { target, directValue: direct!.id };
    } else if (isJS && ["assignment_expression", "augmented_assignment_expression"].includes(node.type)) {
      assignments.push({ node, scope });
      value = node.childForFieldName("right");
      if (value) valueRegion = { target: assignmentTarget(node.childForFieldName("left"), scope), directValue: unwrap(value)!.id };
    } else if (["assignment", "augmented_assignment"].includes(node.type) && !isJS) {
      for (const target of targets(node.childForFieldName("left"))) bind(scope, target, node, unknownTarget);
    }
    if (node.type === "global_statement") for (const part of node.namedChildren) {
      if (part.type === "identifier") bind(global, identifier(part), node, unknownTarget);
    }
    if (isJS && node.type === "import_specifier") {
      bind(scope, identifier(node.childForFieldName("alias") ?? node.childForFieldName("name")), node, unknownTarget);
    } else if (isJS && ["import_clause", "namespace_import", "import_require_clause"].includes(node.type)) {
      for (const part of node.namedChildren.filter(child => child.type === "identifier")) bind(scope, identifier(part), node, unknownTarget);
    } else if (language === "python" && ["import_statement", "import_from_statement"].includes(node.type)) {
      const module = node.childForFieldName("module_name");
      for (const part of node.namedChildren.filter(child => child.id !== module?.id)) {
        const imported = part.childForFieldName("name") ?? part;
        const name = part.childForFieldName("alias") ?? imported.namedChildren.find(child => child.type === "identifier") ?? imported;
        if (["identifier", "dotted_name", "aliased_import"].includes(part.type)) bind(scope, identifier(name), node, unknownTarget);
        else if (part.type === "wildcard_import") scope.unknownBindings = true;
      }
    }
    // Value propagation belongs to this region, never to an ancestor search.
    const fence = isClass || isFunction || ["public_field_definition", "field_definition", "pair", "object",
      "return_statement", "expression_statement", "class_static_block"].includes(node.type);
    for (const child of node.namedChildren) scan(child, scope, child.id === value?.id ? valueRegion : fence ? undefined : region);
  };
  scan(root, global);
  // Resolve writes after all declarations are indexed (including hoisted or
  // later lexical bindings), so traversal order cannot invent a known class.
  for (const { node, scope } of assignments) for (const name of targets(node.childForFieldName("left"))) {
    if (name === null) {
      for (let current: Scope | null = scope; current; current = current.parent) current.unknownBindings = true;
      continue;
    }
    const found = lookup(scope, name);
    if (found === null) continue;
    const right = unwrap(node.childForFieldName("right"));
    const target = right && classExpression(right) ? facts.get(right.id)?.classTarget ?? unknownTarget : unknownTarget;
    bind(found?.scope ?? global, name, node, target);
  }
  const get = (node: Node) => facts.get(node.id)!;
  return {
    declaration: (node: Node) => get(node).declaration(),
    receiver: (node: Node) => get(node).receiver(),
    classTarget: (node: Node) => get(node).classTarget?.() ?? UNKNOWN_SCOPE,
    reference(node: Node, name: string): SymbolScope {
      const found = lookup(get(node).scope, name);
      if (!found) return UNKNOWN_SCOPE;
      const distinct = new Map([...found.values.values()].map(resolve => { const value = resolve(); return [JSON.stringify(value), value]; }));
      return distinct.size === 1 ? [...distinct.values()][0] : UNKNOWN_SCOPE;
    },
    unbound: (node: Node, name: string) => lookup(get(node).scope, name) === undefined,
  };
}

class TreeSitterPlugin implements AnalyzerPlugin {
  readonly name = "tree-sitter";
  readonly languages: string[];

  private configs: LanguageConfig[];

  // Pre-loaded parser constructor and languages (set by init())
  private _ParserClass:
    | (new () => TreeSitterParser)
    | null = null;
  private _languages = new Map<string, TreeSitterLanguage>();
  private _extensionToLang = new Map<string, string>();
  // One reusable parser per language key. web-tree-sitter parsers are reusable
  // across parse() calls (only the Tree is per-parse, and it's still deleted);
  // creating + setLanguage + delete on every call wasted an allocation and a
  // WASM setLanguage on every file. Cached here, created lazily on first use.
  private _parsers = new Map<string, TreeSitterParser>();
  private _initialized = false;

  // Language-specific extractors (keyed by language id)
  private extractors = new Map<string, LanguageExtractor>();

  /**
   * Create a TreeSitterPlugin with the given language configs.
   * Only configs that have a `treeSitter` field will be loaded.
   * If no configs are provided, defaults to TypeScript and JavaScript.
   *
   * @param configs Language configurations to load
   * @param extractors Optional language extractors; if none provided, registers all builtin extractors
   */
  constructor(configs?: LanguageConfig[], extractors?: LanguageExtractor[]) {
    if (configs) {
      this.configs = configs.filter((c) => c.treeSitter);
    } else {
      // Default: TS/JS for backward compatibility
      this.configs = [];
    }

    // Derive supported languages and extension map from configs
    const langs: string[] = [];
    for (const config of this.configs) {
      langs.push(config.id);
      for (const ext of config.extensions) {
        const key = ext.startsWith(".") ? ext : `.${ext}`;
        this._extensionToLang.set(key, config.id);
      }
    }

    // Fallback for backward compat when no configs provided
    if (langs.length === 0) {
      langs.push("typescript", "javascript");
      this._extensionToLang.set(".ts", "typescript");
      this._extensionToLang.set(".tsx", "typescript");
      this._extensionToLang.set(".js", "javascript");
      this._extensionToLang.set(".mjs", "javascript");
      this._extensionToLang.set(".cjs", "javascript");
      this._extensionToLang.set(".jsx", "javascript");
    }

    this.languages = langs;

    // Register extractors (default: all builtin extractors)
    if (extractors && extractors.length > 0) {
      for (const extractor of extractors) {
        this.registerExtractor(extractor);
      }
    } else {
      for (const extractor of builtinExtractors) {
        this.registerExtractor(extractor);
      }
    }
  }

  registerExtractor(extractor: LanguageExtractor): void {
    for (const id of extractor.languageIds) {
      this.extractors.set(id, extractor);
    }
  }

  private getExtractor(langKey: string): LanguageExtractor | null {
    // tsx is a synthetic grammar key — extraction logic is identical to typescript
    const key = langKey === "tsx" ? "typescript" : langKey;
    return this.extractors.get(key) ?? null;
  }

  private languageKeyFromPath(filePath: string): string | null {
    const ext = extname(filePath).toLowerCase();

    // Special case: .tsx needs its own grammar
    if (ext === ".tsx") return "tsx";

    return this._extensionToLang.get(ext) ?? null;
  }

  /**
   * Initialize the plugin by loading the WASM module and all language grammars.
   * Must be called (and awaited) before any synchronous methods.
   */
  async init(): Promise<void> {
    if (this._initialized) return;

    const mod = await import("web-tree-sitter");
    const ParserCls = mod.Parser;
    const LanguageCls = mod.Language;

    await ParserCls.init();
    this._ParserClass = ParserCls as unknown as new () => TreeSitterParser;

    if (this.configs.length > 0) {
      // Load grammars from configs
      const loadPromises: Promise<void>[] = [];

      for (const config of this.configs) {
        if (!config.treeSitter) continue;

        const loadGrammar = async () => {
          try {
            const wasmPath = require.resolve(
              `${config.treeSitter!.wasmPackage}/${config.treeSitter!.wasmFile}`,
            );
            const lang = await LanguageCls.load(wasmPath);
            this._languages.set(config.id, lang);

            // Special handling for TypeScript: also load TSX grammar
            if (config.id === "typescript") {
              try {
                const tsxWasm = require.resolve(
                  `${config.treeSitter!.wasmPackage}/tree-sitter-tsx.wasm`,
                );
                const tsxLang = await LanguageCls.load(tsxWasm);
                this._languages.set("tsx", tsxLang);
              } catch {
                // TSX grammar not available; .tsx files will fall back to TS grammar
              }
            }
          } catch {
            // Grammar not available — this language will be skipped gracefully
            console.debug?.(
              `tree-sitter: Could not load grammar for ${config.id}, skipping structural analysis`,
            );
          }
        };

        loadPromises.push(loadGrammar());
      }

      await Promise.all(loadPromises);
    } else {
      // Legacy fallback: load TS/JS grammars directly
      const tsWasm = require.resolve(
        "tree-sitter-typescript/tree-sitter-typescript.wasm",
      );
      const tsxWasm = require.resolve(
        "tree-sitter-typescript/tree-sitter-tsx.wasm",
      );
      const jsWasm = require.resolve(
        "tree-sitter-javascript/tree-sitter-javascript.wasm",
      );

      const [tsLang, tsxLang, jsLang] = await Promise.all([
        LanguageCls.load(tsWasm),
        LanguageCls.load(tsxWasm),
        LanguageCls.load(jsWasm),
      ]);

      this._languages.set("typescript", tsLang);
      this._languages.set("tsx", tsxLang);
      this._languages.set("javascript", jsLang);
    }

    this._initialized = true;
  }

  /**
   * Create a parser set to the appropriate language for the given file.
   * This is synchronous because all languages are pre-loaded during init().
   */
  private getParser(filePath: string): TreeSitterParser | null {
    if (!this._initialized || !this._ParserClass) {
      throw new Error(
        "TreeSitterPlugin.init() must be called before use",
      );
    }
    const langKey = this.languageKeyFromPath(filePath);
    if (!langKey) return null;
    const lang = this._languages.get(langKey);
    if (!lang) {
      // Language grammar not loaded — graceful degradation
      return null;
    }
    let parser = this._parsers.get(langKey);
    if (!parser) {
      parser = new this._ParserClass();
      parser.setLanguage(lang);
      this._parsers.set(langKey, parser);
    }
    return parser;
  }

  // Fresh object AND fresh arrays on every call — a shared static would leak
  // the same array instances to every caller, so one caller mutating its
  // result would corrupt everyone else's.
  private static emptyStructure(): StructuralAnalysis {
    return { functions: [], classes: [], imports: [], exports: [] };
  }

  analyzeFile(
    filePath: string,
    content: string,
  ): StructuralAnalysis {
    const parser = this.getParser(filePath);
    if (!parser) {
      return { functions: [], classes: [], imports: [], exports: [] };
    }

    const tree = parser.parse(content);
    if (!tree) {
      return { functions: [], classes: [], imports: [], exports: [] };
    }

    const langKey = this.languageKeyFromPath(filePath);
    const extractor = langKey ? this.getExtractor(langKey) : null;

    let result: StructuralAnalysis;
    if (extractor) {
      result = extractor.extractStructure(tree.rootNode);
    } else {
      result = { functions: [], classes: [], imports: [], exports: [] };
    }

    tree.delete();

    return result;
  }

  /**
   * Evidence for destructive structural comparisons. Unlike analyzeFile's
   * best-effort contract, an unavailable grammar or a recovered syntax error
   * must never look like a successfully parsed file with no symbols.
   * Supplemental declarations retain their name and owner, so uncertainty
   * cannot leak from an unrelated class or an ordinary source-code token.
   */
  analyzeFileStrict(
    filePath: string,
    content: string,
  ): {
    status: "succeeded" | "unsupported" | "failed";
    structure: StructuralAnalysis | null;
    symbolEvidence: SymbolEvidence | null;
    language?: string;
  } {
    let tree: ReturnType<TreeSitterParser["parse"]> = null;
    try {
      const parser = this.getParser(filePath);
      const langKey = this.languageKeyFromPath(filePath);
      const extractor = langKey ? this.getExtractor(langKey) : null;
      if (!parser || !extractor) {
        return { status: "unsupported", structure: null, symbolEvidence: null };
      }
      tree = parser.parse(content);
      if (!tree || tree.rootNode.hasError) {
        return { status: "failed", structure: null, symbolEvidence: null };
      }
      const structure = extractor.extractStructure(tree.rootNode);
      return {
        status: "succeeded",
        language: langKey!,
        structure,
        symbolEvidence: collectSymbolEvidence(tree.rootNode, structure, langKey!),
      };
    } catch {
      return { status: "failed", structure: null, symbolEvidence: null };
    } finally {
      tree?.delete();
    }
  }

  /**
   * Parse the file ONCE and return both structural analysis and the call
   * graph. `extract-structure.mjs` runs `analyzeFile` then `extractCallGraph`
   * on every code file — two full tree-sitter parses of identical content.
   * Both extractors are pure functions of the same rootNode, so a single
   * parse yields byte-identical results (verified) at ~40% less parse work
   * on the indexing hot path. Callers without this method fall back to the
   * two separate calls.
   */
  analyzeFileFull(
    filePath: string,
    content: string,
  ): { structure: StructuralAnalysis; callGraph: CallGraphEntry[] } {
    const parser = this.getParser(filePath);
    if (!parser) {
      return { structure: TreeSitterPlugin.emptyStructure(), callGraph: [] };
    }

    const tree = parser.parse(content);
    if (!tree) {
      return { structure: TreeSitterPlugin.emptyStructure(), callGraph: [] };
    }

    const langKey = this.languageKeyFromPath(filePath);
    const extractor = langKey ? this.getExtractor(langKey) : null;

    const structure = extractor
      ? extractor.extractStructure(tree.rootNode)
      : TreeSitterPlugin.emptyStructure();
    const callGraph = extractor ? extractor.extractCallGraph(tree.rootNode) : [];

    tree.delete();

    return { structure, callGraph };
  }

  resolveImports(
    filePath: string,
    content: string,
  ): ImportResolution[] {
    const analysis = this.analyzeFile(filePath, content);
    const dir = dirname(filePath);

    return analysis.imports.map((imp) => {
      let resolvedPath: string;
      if (
        imp.source.startsWith("./") ||
        imp.source.startsWith("../")
      ) {
        resolvedPath = resolve(dir, imp.source);
      } else {
        resolvedPath = imp.source;
      }
      return {
        source: imp.source,
        resolvedPath,
        specifiers: imp.specifiers,
      };
    });
  }

  extractCallGraph(
    filePath: string,
    content: string,
  ): CallGraphEntry[] {
    const parser = this.getParser(filePath);
    if (!parser) return [];

    const tree = parser.parse(content);
    if (!tree) {
      return [];
    }

    const langKey = this.languageKeyFromPath(filePath);
    const extractor = langKey ? this.getExtractor(langKey) : null;
    const result = extractor ? extractor.extractCallGraph(tree.rootNode) : [];

    tree.delete();

    return result;
  }
}

