interface I18nContextValue {
  locale: Locale;
  localeKey: LocaleKey;
  t: Locale;
}

function useI18n(): I18nContextValue {
  const ctx = useContext(I18nContext);
  if (!ctx) {
    throw new Error("useI18n must be used within an I18nProvider");
  }
  return ctx;
}

function I18nProvider({
  language,
  children,
}: {
  language?: string;
  children: ReactNode;
}) {
  const localeKey = useMemo(() => resolveLocaleKey(language), [language]);
  const locale = useMemo(() => getLocale(localeKey), [localeKey]);

  const value = useMemo(
    () => ({
      locale,
      localeKey,
      t: locale,
    }),
    [locale, localeKey]
  );

  return (
    <I18nContext.Provider value={value}>
      {children}
    </I18nContext.Provider>
  );
}

type GraphFreshnessResult =
  | {
      status: "fresh";
      graphCommitHash: string;
      headCommitHash: string;
      changedFileCount: 0;
      changedFiles: [];
      commitsBehind: 0;
      commitsAhead: 0;
      lastAnalyzedAt?: string;
    }
  | {
      status: "dirty";
      graphCommitHash: string;
      headCommitHash: string;
      changedFileCount: number;
      changedFiles: string[];
      commitsBehind: 0;
      commitsAhead: 0;
      lastAnalyzedAt?: string;
    }
  | {
      status: "stale";
      relation: GraphFreshnessRelation;
      graphCommitHash: string;
      headCommitHash: string;
      changedFileCount: number;
      changedFiles: string[];
      commitsBehind: number;
      commitsAhead: number;
      lastAnalyzedAt?: string;
    }
  | {
      status: "unknown";
      reason: GraphFreshnessUnknownReason;
      graphCommitHash?: string;
      headCommitHash?: string;
      lastAnalyzedAt?: string;
    };

interface DashboardFreshnessReport {
  graphs: {
    knowledge: GraphFreshnessResult;
    domain?: GraphFreshnessResult;
  };
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isNonEmptyString(value: unknown): value is string {
  return typeof value === "string" && value.length > 0;
}

function isOptionalString(record: Record<string, unknown>, key: string): boolean {
  return !(key in record) || typeof record[key] === "string";
}

function isOptionalHash(record: Record<string, unknown>, key: string): boolean {
  return !(key in record) || isNonEmptyString(record[key]);
}

function isNonNegativeInteger(value: unknown): value is number {
  return Number.isInteger(value) && (value as number) >= 0;
}

function isChangedFileList(value: unknown): value is string[] {
  return Array.isArray(value) && value.every((file) => typeof file === "string");
}

function isGraphFreshnessResult(
  value: unknown,
): value is GraphFreshnessResult {
  if (!isRecord(value) || typeof value.status !== "string") return false;
  if (!isOptionalString(value, "lastAnalyzedAt")) return false;

  if (value.status === "unknown") {
    return (
      typeof value.reason === "string" &&
      UNKNOWN_REASONS.has(value.reason as GraphFreshnessUnknownReason) &&
      isOptionalHash(value, "graphCommitHash") &&
      isOptionalHash(value, "headCommitHash")
    );
  }

  if (
    !isNonEmptyString(value.graphCommitHash) ||
    !isNonEmptyString(value.headCommitHash) ||
    !isNonNegativeInteger(value.changedFileCount) ||
    !isChangedFileList(value.changedFiles) ||
    value.changedFileCount !== value.changedFiles.length ||
    !isNonNegativeInteger(value.commitsBehind) ||
    !isNonNegativeInteger(value.commitsAhead)
  ) {
    return false;
  }

  if (value.status === "fresh") {
    return (
      value.changedFileCount === 0 &&
      value.commitsBehind === 0 &&
      value.commitsAhead === 0
    );
  }

  if (value.status === "dirty") {
    return (
      value.changedFileCount > 0 &&
      value.commitsBehind === 0 &&
      value.commitsAhead === 0
    );
  }

  if (value.status === "stale") {
    return (
      value.changedFileCount > 0 &&
      typeof value.relation === "string" &&
      RELATIONS.has(value.relation as GraphFreshnessRelation)
    );
  }

  return false;
}

function isDashboardFreshnessReport(
  value: unknown,
): value is DashboardFreshnessReport {
  if (!isRecord(value) || !isRecord(value.graphs)) return false;
  if (!isGraphFreshnessResult(value.graphs.knowledge)) return false;
  return (
    !("domain" in value.graphs) ||
    isGraphFreshnessResult(value.graphs.domain)
  );
}

function shouldRequestFreshness(
  demoMode: boolean,
  demoFreshnessUrl?: string,
): boolean {
  return !demoMode || Boolean(demoFreshnessUrl);
}

async function requestFreshnessReport(
  url: string,
  signal: AbortSignal,
  fetcher: typeof fetch = fetch,
): Promise<DashboardFreshnessReport> {
  const response = await fetcher(url, { signal, cache: "no-store" });
  if (!response.ok) throw new Error("Freshness request failed");

  const payload: unknown = await response.json();
  if (!isDashboardFreshnessReport(payload)) {
    throw new Error("Freshness response was malformed");
  }
  return payload;
}

interface FreshnessRefreshOptions {
  target: Pick<EventTarget, "addEventListener" | "removeEventListener">;
  load: (signal: AbortSignal) => Promise<DashboardFreshnessReport>;
  onResult: (report: DashboardFreshnessReport) => void;
}

function requestFailedReport(): DashboardFreshnessReport {
  return {
    graphs: {
      knowledge: {
        status: "unknown",
        reason: "freshness-request-failed",
      },
    },
  };
}

function isAbortError(error: unknown): boolean {
  return isRecord(error) && error.name === "AbortError";
}

function startFreshnessRefresh({
  target,
  load,
  onResult,
}: FreshnessRefreshOptions): () => void {
  let activeController: AbortController | null = null;
  let stopped = false;

  const refresh = () => {
    activeController?.abort();
    const controller = new AbortController();
    activeController = controller;

    void load(controller.signal)
      .then((report) => {
        if (
          !stopped &&
          activeController === controller &&
          !controller.signal.aborted
        ) {
          onResult(report);
        }
      })
      .catch((error: unknown) => {
        if (
          stopped ||
          activeController !== controller ||
          controller.signal.aborted ||
          isAbortError(error)
        ) {
          return;
        }
        onResult(requestFailedReport());
      });
  };

  const handleFocus: EventListener = () => refresh();
  target.addEventListener("focus", handleFocus);
  refresh();

  return () => {
    stopped = true;
    target.removeEventListener("focus", handleFocus);
    activeController?.abort();
  };
}

function useIsMobile(breakpoint: number = DEFAULT_BREAKPOINT): boolean {
  const query = `(max-width: ${breakpoint - 1}px)`;
  const [isMobile, setIsMobile] = useState<boolean>(() => {
    if (typeof window === "undefined") return false;
    return window.matchMedia(query).matches;
  });

  useEffect(() => {
    const mql = window.matchMedia(query);
    const handler = (event: MediaQueryListEvent) => setIsMobile(event.matches);
    setIsMobile(mql.matches);
    mql.addEventListener("change", handler);
    return () => mql.removeEventListener("change", handler);
  }, [query]);

  return isMobile;
}

interface KeyboardShortcut {
  key: string;
  ctrlKey?: boolean;
  shiftKey?: boolean;
  altKey?: boolean;
  metaKey?: boolean;
  description: string;
  action: () => void;
  category: string;
}

function useKeyboardShortcuts(
  shortcuts: KeyboardShortcut[],
  enabled = true
) {
  useEffect(() => {
    if (!enabled) return;

    const handleKeyDown = (event: KeyboardEvent) => {
      // Prevent shortcuts from firing when typing in input fields
      const target = event.target as HTMLElement;
      const tagName = target.tagName.toLowerCase();
      if (tagName === 'input' || tagName === 'textarea' || target.isContentEditable) {
        if (event.key !== 'Escape') return;
      }

      for (const shortcut of shortcuts) {
        const keyMatches = event.key.toLowerCase() === shortcut.key.toLowerCase();
        const ctrlMatches = shortcut.ctrlKey ? event.ctrlKey : !event.ctrlKey;
        const shiftMatches = shortcut.shiftKey ? event.shiftKey : !event.shiftKey;
        const altMatches = shortcut.altKey ? event.altKey : !event.altKey;
        const metaMatches = shortcut.metaKey ? event.metaKey : !event.metaKey;

        if (keyMatches && ctrlMatches && shiftMatches && altMatches && metaMatches) {
          // Prevent default for shortcuts that might conflict with browser
          if (event.ctrlKey || event.metaKey || event.altKey) {
            event.preventDefault();
          }
          shortcut.action();
          break;
        }
      }
    };

    document.addEventListener("keydown", handleKeyDown);
    return () => document.removeEventListener("keydown", handleKeyDown);
  }, [shortcuts, enabled]);
}

function formatShortcutKey(shortcut: KeyboardShortcut): string {
  const keys: string[] = [];

  // Use userAgentData with fallback to navigator.platform
  const isMac = (navigator as Navigator & { userAgentData?: { platform: string } }).userAgentData?.platform
    ? (navigator as Navigator & { userAgentData: { platform: string } }).userAgentData.platform === 'macOS'
    : navigator.platform.includes("Mac");

  if (shortcut.ctrlKey || shortcut.metaKey) {
    keys.push(isMac ? "⌘" : "Ctrl");
  }
  // Don't show ⇧ for keys that inherently require Shift (e.g. ?, !, @)
  const isShiftedPunctuation = shortcut.key.length === 1 && /[^a-zA-Z0-9]/.test(shortcut.key);
  if (shortcut.shiftKey && !isShiftedPunctuation) keys.push("⇧");
  if (shortcut.altKey) keys.push(isMac ? "⌥" : "Alt");

  keys.push(isShiftedPunctuation ? shortcut.key : shortcut.key.toUpperCase());

  return keys.join(" + ");
}

function getLocale(key: LocaleKey): Locale {
  return locales[key] ?? locales.en;
}

function resolveLocaleKey(lang: string | undefined): LocaleKey {
  if (!lang) return "en";
  const normalized = lang.toLowerCase().replace(/[_\s]/g, "-");
  if (normalized === "zh" || normalized === "chinese" || normalized === "zh-cn") return "zh";
  if (normalized === "zh-tw" || normalized === "traditional-chinese") return "zh-TW";
  if (normalized === "ja" || normalized === "japanese") return "ja";
  if (normalized === "ko" || normalized === "korean") return "ko";
  if (normalized === "ru" || normalized === "russian" || normalized === "ru-ru") return "ru";
  return "en";
}

interface FilterState {
  nodeTypes: Set<NodeType>;
  complexities: Set<Complexity>;
