function commonPrefix(paths: string[]): string {
  if (paths.length === 0) return "";
  const dirs = paths.map((p) => {
    const slash = p.lastIndexOf("/");
    return slash >= 0 ? p.slice(0, slash) : "";
  });
  let prefix = dirs[0];
  for (const d of dirs) {
    while (!d.startsWith(prefix)) {
      prefix = prefix.slice(0, -1);
      if (!prefix) return "";
    }
  }
  const lastSlash = prefix.lastIndexOf("/");
  return lastSlash >= 0 ? prefix.slice(0, lastSlash + 1) : "";
}

function firstSegment(path: string): string {
  const slash = path.indexOf("/");
  return slash >= 0 ? path.slice(0, slash) : path;
}

function groupByFolder(
  nodes: GraphNode[],
): { groups: Map<string, string[]>; rooted: string[] } {
  const withPath = nodes.filter((n) => n.filePath);
  const lcp = commonPrefix(withPath.map((n) => n.filePath!));
  const groups = new Map<string, string[]>();
  const rooted: string[] = [];
  for (const n of nodes) {
    if (!n.filePath) {
      rooted.push(n.id);
      continue;
    }
    const stripped = n.filePath.slice(lcp.length);
    if (!stripped.includes("/")) {
      rooted.push(n.id);
      continue;
    }
    const seg = firstSegment(stripped);
    const arr = groups.get(seg) ?? [];
    arr.push(n.id);
    groups.set(seg, arr);
  }
  return { groups, rooted };
}

function shouldFallbackToCommunity(
  groups: Map<string, string[]>,
  rooted: string[],
  totalNodes: number,
): boolean {
  const bucketCount = groups.size + (rooted.length > 0 ? 1 : 0);
  if (bucketCount < MIN_BUCKET_COUNT) return true;
  for (const ids of groups.values()) {
    if (ids.length / totalNodes > MAX_CONCENTRATION) return true;
  }
  if (rooted.length / totalNodes > MAX_CONCENTRATION) return true;
  return false;
}

function deriveContainers(
  nodes: GraphNode[],
  edges: GraphEdge[],
): DeriveResult {
  if (nodes.length === 0) {
    return { containers: [], ungrouped: [] };
  }

  const { groups, rooted } = groupByFolder(nodes);

  const useCommunity = shouldFallbackToCommunity(groups, rooted, nodes.length);
  let containers: DerivedContainer[];

  if (useCommunity) {
    const communities = detectCommunities(
      nodes.map((n) => n.id),
      edges,
    );
    const byCommunity = new Map<number, string[]>();
    for (const [nodeId, cid] of communities) {
      const arr = byCommunity.get(cid) ?? [];
      arr.push(nodeId);
      byCommunity.set(cid, arr);
    }
    const sorted = [...byCommunity.entries()].sort((a, b) => a[0] - b[0]);
    containers = sorted.map(([cid, ids], i) => ({
      id: `container:cluster-${cid}`,
      // A-Z for the first 26, then numeric. Avoids `String.fromCharCode(65+i)`
      // wrapping into `[`, `\`, `]` ... once the cluster count exceeds 26.
      name: i < 26 ? `Cluster ${String.fromCharCode(65 + i)}` : `Cluster ${i + 1}`,
      nodeIds: ids,
      strategy: "community" as const,
    }));
  } else {
    containers = [...groups.entries()].map(([seg, ids]) => ({
      id: `container:${seg}`,
      name: seg,
      nodeIds: ids,
      strategy: "folder" as const,
    }));
    if (rooted.length > 0) {
      containers.push({
        id: `container:${ROOT_BUCKET}`,
        name: ROOT_BUCKET,
        nodeIds: rooted,
        strategy: "folder" as const,
      });
    }
  }

  // Suppress single-child containers (their child becomes ungrouped).
  // Skip suppression for tiny layers — with so few nodes, even single-item
  // boxes carry useful folder context that shouldn't be discarded.
  const ungrouped: string[] = [];
  if (nodes.length >= MIN_NODES_FOR_SUPPRESSION) {
    containers = containers.filter((c) => {
      if (c.nodeIds.length === 1) {
        ungrouped.push(c.nodeIds[0]);
        return false;
      }
      return true;
    });
  }

  return { containers, ungrouped };
}

interface LayerEdgeAggregation {
  sourceLayerId: string;
  targetLayerId: string;
  count: number;
  edgeTypes: string[];
}

interface PortalInfo {
  layerId: string;
  layerName: string;
  connectionCount: number;
}

function aggregateLayerEdges(
  graph: KnowledgeGraph,
): LayerEdgeAggregation[] {
  const nodeToLayer = new Map<string, string>();
  for (const layer of graph.layers) {
    for (const nodeId of layer.nodeIds) {
      nodeToLayer.set(nodeId, layer.id);
    }
  }

  // Key: "layerA|layerB" (sorted) → aggregation
  const pairMap = new Map<
    string,
    { sourceLayerId: string; targetLayerId: string; count: number; edgeTypes: Set<string> }
  >();

  for (const edge of graph.edges) {
    const sourceLayer = nodeToLayer.get(edge.source);
    const targetLayer = nodeToLayer.get(edge.target);
    if (!sourceLayer || !targetLayer) continue;
    if (sourceLayer === targetLayer) continue;

    // Canonical key so A→B and B→A merge
    const [a, b] =
      sourceLayer < targetLayer
        ? [sourceLayer, targetLayer]
        : [targetLayer, sourceLayer];
    const key = `${a}|${b}`;

    const existing = pairMap.get(key);
    if (existing) {
      existing.count++;
      existing.edgeTypes.add(edge.type);
    } else {
      pairMap.set(key, {
        sourceLayerId: a,
        targetLayerId: b,
        count: 1,
        edgeTypes: new Set([edge.type]),
      });
    }
  }

  return Array.from(pairMap.values()).map((p) => ({
    sourceLayerId: p.sourceLayerId,
    targetLayerId: p.targetLayerId,
    count: p.count,
    edgeTypes: Array.from(p.edgeTypes),
  }));
}

function computePortals(
  graph: KnowledgeGraph,
  activeLayerId: string,
  precomputed?: LayerEdgeAggregation[],
): PortalInfo[] {
  const aggregated = precomputed ?? aggregateLayerEdges(graph);
  const layerNameMap = new Map(graph.layers.map((l) => [l.id, l.name]));

  const portalMap = new Map<string, number>();

  for (const agg of aggregated) {
    if (agg.sourceLayerId === activeLayerId) {
      portalMap.set(
        agg.targetLayerId,
        (portalMap.get(agg.targetLayerId) ?? 0) + agg.count,
      );
    } else if (agg.targetLayerId === activeLayerId) {
      portalMap.set(
        agg.sourceLayerId,
        (portalMap.get(agg.sourceLayerId) ?? 0) + agg.count,
      );
    }
  }

  return Array.from(portalMap.entries()).map(([layerId, count]) => ({
    layerId,
    layerName: layerNameMap.get(layerId) ?? layerId,
    connectionCount: count,
  }));
}

function findCrossLayerFileNodes(
  graph: KnowledgeGraph,
  activeLayerId: string,
  targetLayerId: string,
): Set<string> {
  const activeNodeIds = new Set(
    graph.layers.find((l) => l.id === activeLayerId)?.nodeIds ?? [],
  );
  const targetNodeIds = new Set(
    graph.layers.find((l) => l.id === targetLayerId)?.nodeIds ?? [],
  );

  const result = new Set<string>();
  for (const edge of graph.edges) {
    if (activeNodeIds.has(edge.source) && targetNodeIds.has(edge.target)) {
      result.add(edge.source);
    }
    if (activeNodeIds.has(edge.target) && targetNodeIds.has(edge.source)) {
      result.add(edge.target);
    }
  }
  return result;
}

interface AggregatedContainerEdge {
  sourceContainerId: string;
  targetContainerId: string;
  count: number;
  edgeTypes: string[];
}

interface ContainerEdgeBuckets {
  intraContainer: GraphEdge[];
  interContainerAggregated: AggregatedContainerEdge[];
}

function aggregateContainerEdges(
  edges: GraphEdge[],
  nodeToContainer: Map<string, string>,
): ContainerEdgeBuckets {
  const intra: GraphEdge[] = [];
  const interMap = new Map<
    string,
    {
      sourceContainerId: string;
      targetContainerId: string;
      count: number;
      edgeTypes: Set<string>;
    }
  >();

  for (const e of edges) {
    const sc = nodeToContainer.get(e.source);
    const tc = nodeToContainer.get(e.target);
    if (!sc || !tc) continue;
    if (sc === tc) {
      intra.push(e);
      continue;
    }
    // Length-prefix the source so container ids containing the separator
    // can't produce key collisions ("X Y" + "Z" vs "X" + "Y Z").
    const key = `${sc.length}:${sc}�${tc}`;
    const existing = interMap.get(key);
    if (existing) {
      existing.count++;
      existing.edgeTypes.add(e.type);
    } else {
      interMap.set(key, {
        sourceContainerId: sc,
        targetContainerId: tc,
        count: 1,
        edgeTypes: new Set([e.type]),
      });
    }
  }

  const interContainerAggregated: AggregatedContainerEdge[] = [...interMap.values()].map(
    (v) => ({
      sourceContainerId: v.sourceContainerId,
      targetContainerId: v.targetContainerId,
      count: v.count,
      edgeTypes: [...v.edgeTypes],
    }),
  );

  return { intraContainer: intra, interContainerAggregated };
}

interface ElkChild {
  id: string;
  width?: number;
  height?: number;
  /** Set by ELK after layout; absent on input. Downstream consumers must default. */
  x?: number;
  y?: number;
  children?: ElkChild[];
  parentId?: string;
}

interface ElkEdge {
  id: string;
  sources: string[];
  targets: string[];
}

interface ElkInput {
  id: string;
  children: ElkChild[];
  edges: ElkEdge[];
  layoutOptions?: Record<string, string>;
}

interface RepairOptions {
  strict?: boolean;
}

interface RepairResult {
  input: ElkInput;
  issues: GraphIssue[];
}

function makeIssue(
  level: GraphIssue["level"],
  category: string,
  message: string,
): GraphIssue {
  return { level, category, message };
}

function maybeThrow(strict: boolean | undefined, issue: GraphIssue): void {
  if (strict) throw new Error(`[ELK repair] ${issue.level}: ${issue.message}`);
}

function repairElkInput(
  input: ElkInput,
  opts: RepairOptions = {},
): RepairResult {
  const issues: GraphIssue[] = [];
  const strict = opts.strict;

  // 1. ensureNodeDimensions
  let dimsAdded = 0;
  const fillDims = (children: ElkChild[]): ElkChild[] =>
    children.map((c) => {
      const next: ElkChild = { ...c };
      if (next.width == null || next.height == null) {
        next.width = next.width ?? DEFAULT_NODE_WIDTH;
        next.height = next.height ?? DEFAULT_NODE_HEIGHT;
        dimsAdded++;
      }
      if (next.children) next.children = fillDims(next.children);
      return next;
    });
  const childrenA = fillDims(input.children);
  if (dimsAdded > 0) {
    const issue = makeIssue(
      "auto-corrected",
      "elk-missing-dimensions",
      `Set default dimensions on ${dimsAdded} node(s) missing width/height.`,
    );
    issues.push(issue);
    maybeThrow(strict, issue);
  }

  // 2. dedupeNodeIds (per parent)
  let dupesRemoved = 0;
  const dedupe = (children: ElkChild[]): ElkChild[] => {
    const seen = new Set<string>();
    const out: ElkChild[] = [];
    for (const c of children) {
      if (seen.has(c.id)) {
        dupesRemoved++;
        continue;
      }
      seen.add(c.id);
      out.push({
        ...c,
        children: c.children ? dedupe(c.children) : undefined,
      });
    }
    return out;
  };
  const childrenB = dedupe(childrenA);
  if (dupesRemoved > 0) {
    const issue = makeIssue(
      "auto-corrected",
      "elk-duplicate-id",
      `Removed ${dupesRemoved} duplicate child id(s).`,
    );
    issues.push(issue);
    maybeThrow(strict, issue);
  }

  // 3. dropOrphanChildren — children whose parentId references nonexistent parent
  const allIds = new Set<string>();
  const walk = (children: ElkChild[]) => {
    for (const c of children) {
      allIds.add(c.id);
      if (c.children) walk(c.children);
    }
  };
  walk(childrenB);
  let orphanChildren = 0;
  const childrenC = childrenB.filter((c) => {
    if (c.parentId && !allIds.has(c.parentId)) {
      orphanChildren++;
      return false;
    }
    return true;
  });
  if (orphanChildren > 0) {
    const issue = makeIssue(
      "dropped",
      "elk-orphan-parent",
      `Dropped ${orphanChildren} child(ren) with missing parent reference.`,
    );
    issues.push(issue);
    maybeThrow(strict, issue);
  }

  // 4. dropOrphanEdges
  let orphanEdges = 0;
  const edges = input.edges.filter((e) => {
    const ok = e.sources.every((s) => allIds.has(s)) &&
      e.targets.every((t) => allIds.has(t));
    if (!ok) {
      orphanEdges++;
      return false;
    }
    return true;
  });
  if (orphanEdges > 0) {
    const issue = makeIssue(
      "dropped",
      "elk-orphan-edge",
      `Dropped ${orphanEdges} edge(s) referencing nonexistent nodes.`,
    );
    issues.push(issue);
    maybeThrow(strict, issue);
  }

  // 5. dropCircularContainment
  const parentOf = new Map<string, string>();
  const fillParents = (children: ElkChild[], parent?: string) => {
    for (const c of children) {
      if (parent) parentOf.set(c.id, parent);
      if (c.children) fillParents(c.children, c.id);
    }
  };
  fillParents(childrenC);
  let cyclesRemoved = 0;
  const isCyclic = (id: string): boolean => {
    const seen = new Set<string>();
    let cur = parentOf.get(id);
    while (cur) {
      if (cur === id || seen.has(cur)) return true;
      seen.add(cur);
      cur = parentOf.get(cur);
    }
    return false;
  };
  const stripCycles = (children: ElkChild[]): ElkChild[] =>
    children
      .filter((c) => {
        if (isCyclic(c.id)) {
          cyclesRemoved++;
          return false;
        }
        return true;
      })
      .map((c) => ({
        ...c,
        children: c.children ? stripCycles(c.children) : undefined,
      }));
  const childrenD = stripCycles(childrenC);
  if (cyclesRemoved > 0) {
    const issue = makeIssue(
      "dropped",
      "elk-containment-cycle",
      `Dropped ${cyclesRemoved} node(s) in containment cycles.`,
    );
    issues.push(issue);
    maybeThrow(strict, issue);
  }

  return {
    input: { ...input, children: childrenD, edges },
    issues,
  };
}

interface ElkLayoutOptions {
  strict?: boolean;
}

interface ElkLayoutResult {
  positioned: ElkInput;
  issues: GraphIssue[];
}

async function applyElkLayout(
  input: ElkInput,
  opts: ElkLayoutOptions = {},
): Promise<ElkLayoutResult> {
  const { input: repaired, issues } = repairElkInput(input, opts);
  try {
    const positioned = (await elk.layout(repaired as never)) as ElkInput;
    return { positioned, issues };
  } catch (err) {
    const fatal: GraphIssue = {
      level: "fatal",
      category: "elk-layout-failed",
      message:
        `ELK layout failed: ${err instanceof Error ? err.message : String(err)}. ` +
        `This looks like a dashboard rendering bug — please file an issue with the copied error.`,
    };
    if (opts.strict) throw err;
    return { positioned: { ...repaired, children: [], edges: [] }, issues: [...issues, fatal] };
  }
}

function filterNodes(
  nodes: GraphNode[],
  nodeIdToLayerIds: Map<string, Set<string>>,
  filters: FilterState,
): GraphNode[] {
  const hasLayerFilter = filters.layerIds.size > 0;
  return nodes.filter((node) => {
    // Filter by node type
    if (!filters.nodeTypes.has(node.type as NodeType)) {
      return false;
    }

    // Filter by complexity
    if (node.complexity && !filters.complexities.has(node.complexity as Complexity)) {
      return false;
    }

    // Filter by layer (if any layers are selected)
    if (hasLayerFilter) {
      const layerIds = nodeIdToLayerIds.get(node.id);
      if (!layerIds) return false;
      let inSelected = false;
      for (const lid of layerIds) {
        if (filters.layerIds.has(lid)) {
          inSelected = true;
          break;
        }
      }
      if (!inSelected) return false;
    }

    return true;
  });
}

function filterEdges(
  edges: GraphEdge[],
  visibleNodeIds: Set<string>,
  filters: FilterState,
): GraphEdge[] {
  return edges.filter((edge) => {
    // Only keep edges between visible nodes
    if (!visibleNodeIds.has(edge.source) || !visibleNodeIds.has(edge.target)) {
      return false;
    }

    // Filter by edge category
    const edgeCategory = getEdgeCategory(edge.type);
    if (edgeCategory && !filters.edgeCategories.has(edgeCategory)) {
      return false;
    }

    return true;
  });
}

function getEdgeCategory(edgeType: string): EdgeCategory | null {
  return EDGE_TYPE_TO_CATEGORY.get(edgeType) ?? null;
}

class ForceLayoutCancelledError extends Error {
  constructor() {
    super("Force layout request was cancelled");
    this.name = "ForceLayoutCancelledError";
  }
}

interface ForceLayoutTask {
  promise: Promise<ForceLayoutPosition[]>;
  cancel: () => void;
}

function startForceLayoutTask(
  request: ForceLayoutRequest,
  createWorker: () => ForceLayoutWorker,
): ForceLayoutTask {
  let worker: ForceLayoutWorker;
  try {
    worker = createWorker();
  } catch (error) {
    return {
      promise: Promise.reject(
        error instanceof Error ? error : new Error(String(error)),
      ),
      cancel: () => {},
    };
  }
  let settled = false;
  let rejectTask: ((reason: unknown) => void) | undefined;

  const cleanup = () => {
    worker.onmessage = null;
    worker.onmessageerror = null;
    worker.onerror = null;
    worker.terminate();
  };

  const promise = new Promise<ForceLayoutPosition[]>((resolve, reject) => {
    rejectTask = reject;

    const fail = (error: Error) => {
      if (settled) return;
      settled = true;
      cleanup();
      reject(error);
    };

    worker.onmessage = (event: MessageEvent<ForceLayoutResponse>) => {
      const response = event.data;
      if (settled) return;
      if (response.requestId !== request.requestId) {
        fail(
          new Error(
            `Force layout worker returned request ${response.requestId}; expected ${request.requestId}`,
          ),
        );
        return;
      }

      if ("error" in response) {
        fail(new Error(`Force layout worker failed: ${response.error}`));
        return;
      }

      settled = true;
      cleanup();
      resolve(response.positions);
    };

    worker.onmessageerror = () => {
      fail(new Error("Force layout worker returned an unreadable response"));
    };

    worker.onerror = (event: ErrorEvent) => {
      event.preventDefault();
      fail(new Error(event.message || "Force layout worker failed"));
    };

    try {
      worker.postMessage(request);
    } catch (error) {
      fail(error instanceof Error ? error : new Error(String(error)));
    }
  });

  return {
    promise,
    cancel: () => {
      if (settled) return;
      settled = true;
      cleanup();
      rejectTask?.(new ForceLayoutCancelledError());
    },
  };
}

function createFallbackGrid(
  nodes: ForceLayoutNode[],
): ForceLayoutPosition[] {
  if (nodes.length === 0) return [];

  const columns = Math.max(1, Math.ceil(Math.sqrt(nodes.length)));
  const cellWidth = nodes.reduce(
    (maximum, node) => Math.max(maximum, node.width),
    0,
  ) + 40;
  const cellHeight = nodes.reduce(
    (maximum, node) => Math.max(maximum, node.height),
    0,
  ) + 40;

  return nodes.map((node, index) => ({
    id: node.id,
    x: (index % columns) * cellWidth,
    y: Math.floor(index / columns) * cellHeight,
  }));
}

interface ForceLayoutNode {
  id: string;
  width: number;
  height: number;
  community?: number;
}

interface ForceLayoutEdge {
  source: string;
  target: string;
}

interface ForceLayoutPosition {
  id: string;
  x: number;
  y: number;
}

interface ForceLayoutRequest {
  requestId: number;
  nodes: ForceLayoutNode[];
  edges: ForceLayoutEdge[];
}

interface ForceLayoutSuccess {
  requestId: number;
  positions: ForceLayoutPosition[];
}

interface ForceLayoutFailure {
  requestId: number;
  error: string;
}

interface SimulationForceNode extends SimulationNodeDatum {
  id: string;
  width: number;
  height: number;
  community?: number;
}

function computeForceLayout(
  nodes: ForceLayoutNode[],
  edges: ForceLayoutEdge[],
): ForceLayoutPosition[] {
  if (nodes.length === 0) return [];

  // Leaving x/y unset lets d3-force use its deterministic phyllotaxis seed.
  // This keeps layouts stable for identical, ordered graph inputs.
  const simulationNodes: SimulationForceNode[] = nodes.map((node) => ({ ...node }));
  const nodeIds = new Set(simulationNodes.map((node) => node.id));
  const simulationLinks: SimulationLinkDatum<SimulationForceNode>[] = edges
    .filter((edge) => nodeIds.has(edge.source) && nodeIds.has(edge.target))
    .map((edge) => ({ source: edge.source, target: edge.target }));

  const communityIds = [
    ...new Set(
      simulationNodes
        .map((node) => node.community)
        .filter((community): community is number => community !== undefined),
    ),
  ].sort((left, right) => left - right);
  const communityIndexById = new Map(
    communityIds.map((community, index) => [community, index]),
  );
  const communityCount = Math.max(1, communityIds.length);
  const communityAngle = (community: number) =>
    (2 * Math.PI * (communityIndexById.get(community) ?? 0)) / communityCount;
  const clusterRadius = Math.max(600, nodes.length * 5);
  const isLarge = nodes.length > 100;
  const chargeStrength = isLarge ? -600 : -350;
  const linkDistance = isLarge ? 250 : 150;

  const simulation = forceSimulation<SimulationForceNode>(simulationNodes)
    .force(
      "link",
      forceLink<SimulationForceNode, SimulationLinkDatum<SimulationForceNode>>(
        simulationLinks,
      )
        .id((node) => node.id)
        .distance(linkDistance)
        .strength(0.2),
    )
    .force("charge", forceManyBody().strength(chargeStrength).distanceMax(1500))
    .force("center", forceCenter(0, 0).strength(0.03))
    .force(
      "collide",
      forceCollide<SimulationForceNode>()
        .radius((node) => Math.max(20, (node.width + 40) / 2))
        .strength(0.8),
    );

  if (communityCount > 1) {
    simulation.force(
      "clusterX",
      forceX<SimulationForceNode>((node) =>
        Math.cos(communityAngle(node.community ?? 0)) * clusterRadius,
      ).strength(0.3),
    );
    simulation.force(
      "clusterY",
      forceY<SimulationForceNode>((node) =>
        Math.sin(communityAngle(node.community ?? 0)) * clusterRadius,
      ).strength(0.3),
    );
  }

  simulation.tick(Math.min(300, Math.max(100, nodes.length)));
  simulation.stop();

  return simulationNodes.map((node) => ({
    id: node.id,
    x: Number.isFinite(node.x) ? (node.x ?? 0) - node.width / 2 : 0,
    y: Number.isFinite(node.y) ? (node.y ?? 0) - node.height / 2 : 0,
  }));
}

interface LayerStats {
  /** Number of layer.nodeIds that resolve to a node in the graph. */
  resolvedCount: number;
  /** Aggregate label for the cluster card; matches the prior 30% threshold. */
  aggregateComplexity: Complexity;
}

function computeLayerStats(
  layer: Layer,
  nodesById: Map<string, GraphNode>,
): LayerStats {
  const counts: Record<Complexity, number> = { simple: 0, moderate: 0, complex: 0 };
  let resolved = 0;
  for (const nid of layer.nodeIds) {
    const node = nodesById.get(nid);
    if (!node) continue;
    resolved++;
    counts[node.complexity]++;
  }
  const aggregateComplexity: Complexity =
    counts.complex > resolved * 0.3
      ? "complex"
      : counts.moderate > resolved * 0.3
        ? "moderate"
        : "simple";
  return { resolvedCount: resolved, aggregateComplexity };
}

function applyDagreLayout(
  nodes: Node[],
  edges: Edge[],
  direction: "TB" | "LR" = "TB",
  nodeDimensions?: Map<string, { width: number; height: number }>,
  spacingOverrides?: { nodesep?: number; ranksep?: number },
): { nodes: Node[]; edges: Edge[] } {
  const g = new dagre.graphlib.Graph();
  g.setDefaultEdgeLabel(() => ({}));

  // Scale spacing for larger graphs to reduce overlap
  const isLarge = nodes.length > 50;
  g.setGraph({
    rankdir: direction,
    nodesep: spacingOverrides?.nodesep ?? (isLarge ? 80 : 60),
    ranksep: spacingOverrides?.ranksep ?? (isLarge ? 120 : 80),
    marginx: 20,
    marginy: 20,
  });

  nodes.forEach((node) => {
    const dims = nodeDimensions?.get(node.id);
    const w = dims?.width ?? NODE_WIDTH;
    const h = dims?.height ?? NODE_HEIGHT;
    g.setNode(node.id, { width: w, height: h });
  });

  edges.forEach((edge) => {
    g.setEdge(edge.source, edge.target);
  });

  dagre.layout(g);

  const layoutedNodes = nodes.map((node) => {
    const pos = g.node(node.id);
    if (!pos) return { ...node, position: { x: 0, y: 0 } };
    const dims = nodeDimensions?.get(node.id);
    const w = dims?.width ?? NODE_WIDTH;
    const h = dims?.height ?? NODE_HEIGHT;
    return {
      ...node,
      position: {
        x: pos.x - w / 2,
        y: pos.y - h / 2,
      },
    };
  });

  return { nodes: layoutedNodes, edges };
}

function nodesToElkInput(
  nodes: Node[],
  edges: Edge[],
  dims: Map<string, { width: number; height: number }>,
  layoutOptionsOverride?: Record<string, string>,
): ElkInput {
  return {
    id: "root",
    layoutOptions: { ...ELK_DEFAULT_LAYOUT_OPTIONS, ...layoutOptionsOverride },
    children: nodes.map((n) => {
      const d = dims.get(n.id);
      return {
        id: n.id,
        width: d?.width ?? NODE_WIDTH,
        height: d?.height ?? NODE_HEIGHT,
      };
    }),
    edges: edges.map((e, i) => ({
      id: e.id ?? `e${i}`,
      sources: [String(e.source)],
      targets: [String(e.target)],
    })),
  };
}

function mergeElkPositions<T extends Node>(
  nodes: T[],
  positioned: ElkInput,
): T[] {
  const positionedMap = new Map<
    string,
    { x: number; y: number; width?: number; height?: number }
  >();
  for (const c of positioned.children ?? []) {
    positionedMap.set(c.id, {
      x: c.x ?? 0,
      y: c.y ?? 0,
      width: c.width,
      height: c.height,
    });
  }
  return nodes.map((n) => {
    const merged = positionedMap.get(n.id);
    if (!merged) {
      return {
        ...n,
        position: n.position ?? { x: 0, y: 0 },
      };
    }
    // Propagate width/height for container nodes so a tick-driven
    // Stage 1 re-layout (Task 15) can resize the visible atom to match
    // the actual Stage 2 footprint. ELK echoes back the same width/height
    // we passed in for non-container nodes, so this is a no-op for them.
    return {
      ...n,
      position: { x: merged.x, y: merged.y },
      ...(merged.width != null ? { width: merged.width } : {}),
      ...(merged.height != null ? { height: merged.height } : {}),
    };
  });
}

